    def _build_ownership_by_category(
        self,
    ) -> dict[SettingsCategoryId, SettingsOwnershipRecord]:
        return {
            record.category: record for record in self._category_ownership_records()
        }

    def _ownership_by_category(
        self,
    ) -> dict[SettingsCategoryId, SettingsOwnershipRecord]:
        return self._ownership_by_category_cache

    @staticmethod
    def _missing_ownership_record(
        category: SettingsCategoryId,
    ) -> SettingsOwnershipRecord:
        logger.warning(
            "Settings ownership record missing for category %s", category.value
        )
        return SettingsOwnershipRecord(
            category=category,
            reads_runtime_state_from=("unknown",),
            writes_allowed=False,
            runtime_owner="Settings ownership matrix",
            boundary_copy="Ownership record missing; update the Settings ownership matrix.",
            recovery_copy="Update the Settings ownership matrix before enabling writes.",
            read_only_reason="Ownership record missing; update matrix before exposing actions.",
        )

    def _ownership_record(
        self, category: SettingsCategoryId
    ) -> SettingsOwnershipRecord:
        return self._ownership_by_category().get(
            category
        ) or self._missing_ownership_record(category)

    def _overview_ownership_rows(self) -> tuple[tuple[str, str], ...]:
        ownership = self._ownership_record(SettingsCategoryId.OVERVIEW)
        return (*SETTINGS_OVERVIEW_BOUNDARY_ROWS, ("Recovery", ownership.recovery_copy))

    def _active_summary(self) -> SettingsCategorySummary:
        for summary in self._category_summaries():
            if summary.category.value == self.active_category:
                return summary
        return self._category_summaries()[0]

    def _app_config_section_target(self):
        app_config = getattr(self.app_instance, "app_config", None)
        if callable(getattr(app_config, "setdefault", None)) and hasattr(
            app_config, "__setitem__"
        ):
            return app_config
        self.app_instance.app_config = {}
        return self.app_instance.app_config

    def _console_settings(self) -> dict:
        app_config = self._app_config_section_target()
        console_settings = app_config.setdefault("console", {})
        if not isinstance(console_settings, dict):
            console_settings = {}
            app_config["console"] = console_settings
        return console_settings

    def _loaded_raw_cli_permitted(self) -> bool:
        """Return the strict persisted raw CLI unlock from live app config."""
        app_config = getattr(self.app_instance, "app_config", None)
        if not isinstance(app_config, Mapping):
            return False
        console = app_config.get("console")
        return isinstance(console, Mapping) and console.get("raw_cli_permitted") is True

    def _raw_cli_runtime(self) -> Any | None:
        """Return the app-owned launch-local raw CLI runtime, when available."""
        return getattr(self.app_instance, "raw_cli_runtime", None)

    def _raw_cli_draft_value(self) -> bool:
        draft = self._settings_drafts.get(SettingsCategoryId.PRIVACY_SECURITY)
        if draft is not None and RAW_CLI_PERMITTED_DRAFT_KEY in draft.values:
            return draft.values[RAW_CLI_PERMITTED_DRAFT_KEY] is True
        return self._loaded_raw_cli_permitted()

    def _stage_raw_cli_permitted(self, value: bool) -> None:
        category = SettingsCategoryId.PRIVACY_SECURITY
        draft = self._settings_drafts.setdefault(category, SettingsDraft(category))
        draft.set_value(
            RAW_CLI_PERMITTED_DRAFT_KEY,
            self._loaded_raw_cli_permitted(),
            bool(value),
        )
        self._update_draft_status_widgets(category)
        self._refresh_raw_cli_state()
        self._refresh_terminal_state()

    def _raw_cli_is_armed(self) -> bool:
        runtime = self._raw_cli_runtime()
        return bool(runtime is not None and getattr(runtime, "armed", False))

    def _raw_cli_state_text(self) -> str:
        if self._raw_cli_is_armed():
            return "ARMED — HOST SHELL"
        if self._loaded_raw_cli_permitted():
            return "Unlocked, not armed"
        return "Locked"

    def _raw_cli_arm_button_state(self) -> tuple[str, bool]:
        if self._raw_cli_is_armed():
            return "Disarm raw CLI", False
        if self._loaded_raw_cli_permitted() and not self._category_has_unsaved_changes(
            SettingsCategoryId.PRIVACY_SECURITY
        ):
            return "Arm raw CLI", False
        return "Save unlock first", True

    def _terminal_runtime(self) -> Any | None:
        """Return the app-owned launch-local Terminal manager, when available."""
        return getattr(self.app_instance, "terminal_session_manager", None)

    def _terminal_is_armed(self) -> bool:
        runtime = self._terminal_runtime()
        return bool(runtime is not None and getattr(runtime, "armed", False))

    def _terminal_state_text(self) -> str:
        if self._terminal_is_armed():
            return "ARMED — HOST TERMINAL"
        if self._loaded_raw_cli_permitted():
            return "Unlocked, not armed"
        return "Locked"

    def _terminal_arm_button_state(self) -> tuple[str, bool]:
        if self._terminal_is_armed():
            return "Disarm Terminal", False
        if self._loaded_raw_cli_permitted() and not self._category_has_unsaved_changes(
            SettingsCategoryId.PRIVACY_SECURITY
        ):
            return "Arm Terminal", False
        return "Save unlock first", True

    def _terminal_live_session_count(self) -> int | None:
        """Return the live retained-session count, or None when unavailable."""
        runtime = self._terminal_runtime()
        if runtime is None:
            return 0
        try:
            projections = tuple(runtime.projections())
        except Exception:
            logger.exception(
                "Failed to inspect Terminal sessions before disarm "
                "(runtime_type=%s)",
                type(runtime).__name__,
            )
            return None
        count = 0
        for projection in projections:
            lifecycle = getattr(projection, "lifecycle", None)
            lifecycle_value = getattr(lifecycle, "value", lifecycle)
            if lifecycle_value in {
                "reserved",
                "creating",
                "admitting",
                "running",
                "draining",
                "closing",
            }:
                count += 1
        return count

    def _disarm_terminal_runtime(
        self, runtime: Any, *, session_count: int | None
    ) -> None:
        """Revoke Terminal authority and report its content-free cleanup state."""
        runtime.disarm()
        self._refresh_terminal_state()
        self._refresh_raw_cli_state()
        if session_count:
            self.app.notify(
                "Terminal disarmed. Cleanup started for "
                f"{session_count} sessions; pending or unproven cleanup remains "
                "available in Terminal.",
                severity="warning",
            )
        elif session_count is None:
            self.app.notify(
                "Terminal disarmed. Session cleanup status could not be inspected; "
                "check Terminal for pending or unproven cleanup.",
                severity="warning",
            )
        else:
            self.app.notify("Terminal disarmed for this launch.", severity="warning")

    def _host_access_is_armed(self) -> bool:
        return self._raw_cli_is_armed() or self._terminal_is_armed()

    def _refresh_host_access_card(self) -> None:
        try:
            card = self.query_one("#settings-raw-cli-card")
        except QueryError:
            return
        card.set_class(self._host_access_is_armed(), "settings-raw-cli-armed")

    def _refresh_raw_cli_state(self) -> None:
        """Refresh raw CLI authority from persisted config and runtime only."""
        try:
            state = self.query_one("#settings-raw-cli-state", Static)
            button = self.query_one("#settings-raw-cli-arm", Button)
        except QueryError:
            return
        self._refresh_host_access_card()
        state.update(self._raw_cli_state_text())
        label, disabled = self._raw_cli_arm_button_state()
        button.label = label
        button.disabled = disabled
        button.refresh(layout=True)

    def _refresh_terminal_state(self) -> None:
        """Refresh Terminal authority from persisted config and manager state."""
        try:
            state = self.query_one("#settings-terminal-state", Static)
            banner = self.query_one("#settings-terminal-host-access", Static)
            button = self.query_one("#settings-terminal-arm", Button)
        except QueryError:
            return
        self._refresh_host_access_card()
        armed = self._terminal_is_armed()
        state.update(self._terminal_state_text())
        banner.update("HOST TERMINAL - FULL USER ACCESS" if armed else "")
        label, disabled = self._terminal_arm_button_state()
        button.label = label
        button.disabled = disabled
        button.refresh(layout=True)

    def _sync_raw_cli_widgets(self) -> None:
        try:
            checkbox = self.query_one("#settings-raw-cli-permitted", Checkbox)
        except QueryError:
            self._refresh_raw_cli_state()
            return
        with checkbox.prevent(Checkbox.Changed):
            checkbox.value = self._raw_cli_draft_value()
        self._refresh_raw_cli_state()
        self._refresh_terminal_state()

    def _chat_defaults(self) -> dict:
        app_config = self._app_config_section_target()
        chat_defaults = app_config.setdefault("chat_defaults", {})
        if not isinstance(chat_defaults, dict):
            chat_defaults = {}
            app_config["chat_defaults"] = chat_defaults
        return chat_defaults

    def _loaded_collapse_large_pastes_enabled(self) -> bool:
        return coerce_bool_setting(
            self._console_settings().get("collapse_large_pastes", True),
            True,
        )

    def _loaded_show_model_thinking(self) -> bool:
        return load_show_model_thinking(self._console_settings())

    def _loaded_thinking_history_policy_default(self) -> str:
        return load_thinking_history_policy_default(self._console_settings())

    def _show_model_thinking_label(self) -> str:
        state = "On" if self._loaded_show_model_thinking() else "Off"
        return f"Show model thinking ({state})"

    def _loaded_stack_collapsed_rail_labels(self) -> bool:
        """Return the saved collapsed-rail presentation preference."""
        return coerce_bool_setting(
            self._console_settings().get("stack_collapsed_rail_labels", False),
            False,
        )

    def _loaded_console_rail_layout_scope(self) -> str:
        """Return the normalized saved rail-layout persistence scope."""
        return normalize_console_rail_layout_scope(
            self._console_settings().get("rail_layout_scope")
        )

    def _loaded_paste_collapse_threshold(self) -> int:
        return coerce_int_setting(
            self._console_settings().get(
                "paste_collapse_threshold",
                DEFAULT_CONSOLE_PASTE_COLLAPSE_THRESHOLD,
            ),
            DEFAULT_CONSOLE_PASTE_COLLAPSE_THRESHOLD,
            minimum=MIN_CONSOLE_PASTE_COLLAPSE_THRESHOLD,
            maximum=MAX_CONSOLE_PASTE_COLLAPSE_THRESHOLD,
        )

    def _loaded_console_max_parallel_runs(self) -> int:
        # No maximum -- deliberately unbounded (user-owned trade-off), see
        # DEFAULT_CONSOLE_MAX_PARALLEL_RUNS's docstring.
        return coerce_int_setting(
            self._console_settings().get(
                "max_parallel_runs",
                DEFAULT_CONSOLE_MAX_PARALLEL_RUNS,
            ),
            DEFAULT_CONSOLE_MAX_PARALLEL_RUNS,
            minimum=MIN_CONSOLE_MAX_PARALLEL_RUNS,
        )

    def _saved_permission_summary_payload(self) -> dict[str, str]:
        """The normalized saved ``[permission_summary]`` trio (ADR-090).

        Reads the cached ``load_settings()`` config -- the model-catalog
        group's source (cheap cache hit, and every config write refreshes
        it) -- and normalizes through the settings payload helper, so
        compose-time widget values and the instant-apply no-op guard can
        never disagree about what "saved" means.
        """
        from ...Chat.permission_summary_service import (
            permission_summary_settings_payload,
        )

        section = load_settings().get("permission_summary")
        section = section if isinstance(section, dict) else {}
        return permission_summary_settings_payload(
            str(section.get("mode") or ""),
            str(section.get("provider") or ""),
            str(section.get("model") or ""),
        )

    def _loaded_agent_budget_value(self, field: AgentBudgetField) -> float:
        """The saved (or shipped-default) value for one budget field.

        Mirrors `console_agent_bridge.console_run_budget()`'s own
        coercion, floors included, so Settings can never display a value
        the run path would reject and silently replace.
        """
        raw = self._console_settings().get(field.key, field.default)
        if field.is_float:
            return coerce_float_setting(
                raw, float(field.default), minimum=field.minimum
            )
        return coerce_int_setting(raw, int(field.default), minimum=int(field.minimum))

    def _agent_budget_value(self, field: AgentBudgetField) -> float | str:
        """The value to display: the staged draft if any, else the saved one.

        Returns a `str` when the draft holds text that failed validation,
        so the user's in-progress typing survives a re-render.
        """
        draft = self._settings_drafts.get(SettingsCategoryId.CONSOLE_BEHAVIOR)
        if draft is not None and field.key in draft.values:
            return draft.values[field.key]
        return self._loaded_agent_budget_value(field)

    def _normalise_agent_budget_value(
        self, field: AgentBudgetField, value: object
    ) -> float:
        """Coerce one budget field's input, or raise with a usable message.

        Floors only -- no ceiling is enforced anywhere in this feature
        (owner decision: these are user-owned trade-offs, same call as
        `max_parallel_runs`). A below-floor value is REFUSED rather than
        clamped: silently running at a number the user did not choose is
        how a 2000-turn budget quietly becomes an 8-turn one.

        Raises:
            ValueError: With copy naming the field and its floor.
        """
        text_value = str(value).strip()
        try:
            parsed = float(text_value) if field.is_float else int(text_value)
        except (TypeError, ValueError):
            kind = "number" if field.is_float else "whole number"
            raise ValueError(
                f"{field.label} must be a {kind} of at least "
                f"{self._format_agent_budget_number(field, field.minimum)}."
            ) from None
        if parsed != parsed or parsed in (float("inf"), float("-inf")):
            raise ValueError(f"{field.label} must be a finite number.")
        if parsed < field.minimum:
            raise ValueError(
                f"{field.label} must be at least "
                f"{self._format_agent_budget_number(field, field.minimum)} "
                f"{field.unit}."
            )
        return float(parsed) if field.is_float else int(parsed)

    @staticmethod
    def _format_agent_budget_number(field: AgentBudgetField, value: float) -> str:
        """Render a budget number without a pointless trailing '.0'."""
        if field.is_float:
            return f"{value:g}"
        return str(int(value))

    def _stage_agent_budget_value(self, field: AgentBudgetField, value: object) -> None:
        category = SettingsCategoryId.CONSOLE_BEHAVIOR
        draft = self._settings_drafts.setdefault(
            category, SettingsDraft(category=category)
        )
        try:
            staged_value: object = self._normalise_agent_budget_value(field, value)
        except ValueError:
            # Keep the raw text staged so the user's typing is not eaten
            # mid-edit; the save path re-normalises and reports the error.
            staged_value = str(value)
        draft.set_value(
            field.key,
            self._loaded_agent_budget_value(field),
            staged_value,
        )
        if not draft.is_dirty:
            self._settings_drafts.pop(category, None)

    @staticmethod
    def _humanise_seconds(seconds: float) -> str:
        """Render a seconds count as a duration a human can sanity-check.

        86400 is not a number anyone reads as "24 hours" at a glance, and
        this field's whole purpose is letting someone set a very large one
        deliberately. Rendered beside the input, live as they type.
        """
        try:
            total = float(seconds)
        except (TypeError, ValueError):
            return ""
        if total <= 0:
            return "unlimited" if total == 0 else ""
        minutes, secs = divmod(int(total), 60)
        hours, minutes = divmod(minutes, 60)
        days, hours = divmod(hours, 24)
        parts = []
        if days:
            parts.append(f"{days}d")
        if hours:
            parts.append(f"{hours}h")
        if minutes:
            parts.append(f"{minutes}m")
        if secs and not days:
            parts.append(f"{secs}s")
        return " ".join(parts) or "0s"

    def _agent_budget_hint(self, field: AgentBudgetField) -> str:
        """The live, value-dependent prefix for one field's help line.

        Carries what the raw number does not: 86400 rendered as "24h", 0
        named as the unlimited case it actually is, and a validation error
        stated in place instead of only at save time.
        """
        value = self._agent_budget_value(field)
        try:
            numeric = self._normalise_agent_budget_value(field, value)
        except ValueError as exc:
            return str(exc)
        if field.is_float:
            if numeric == 0:
                return "0 = unlimited."
            return f"= {self._humanise_seconds(numeric)}."
        if field.key == "agent_max_total_tokens" and numeric == 0:
            return "0 = unlimited - no runaway-spend backstop."
        return ""

    def _agent_budget_help_text(self, field: AgentBudgetField) -> str:
        """One field's full help line: live hint first, then static copy.

        Rendered into a single Static (not a hint widget beside the input)
        so it uses the same `settings-detail-row` styling every other
        Console help line already has, rather than needing a new class.
        """
        hint = self._agent_budget_hint(field)
        return f"{hint} {field.help_text}".strip() if hint else field.help_text

    def _agent_budget_step_floor_warning(self) -> str:
        """Warn when the step backstop will bind before the turn cap.

        A fence tool round costs 3 steps and the closing reply costs 1, so
        N turns need `3*(N-1)+1` steps. Set steps below that and a run
        stops on "step budget exhausted" well before the turn cap the user
        actually configured -- a silent misconfiguration with a confusing
        symptom. Non-blocking by design: it is a legitimate thing to want
        (a hard step ceiling), just never a thing to want by accident.
        """
        turns_field = AGENT_BUDGET_FIELDS_BY_KEY["agent_max_model_turns"]
        steps_field = AGENT_BUDGET_FIELDS_BY_KEY["agent_max_steps"]
        try:
            turns = int(
                self._normalise_agent_budget_value(
                    turns_field, self._agent_budget_value(turns_field)
                )
            )
            steps = int(
                self._normalise_agent_budget_value(
                    steps_field, self._agent_budget_value(steps_field)
                )
            )
        except ValueError:
            return ""
        needed = 3 * (turns - 1) + 1
        if steps >= needed:
            return ""
        return (
            f"Note: {steps} steps caps this run at about "
            f"{max(1, (steps - 1) // 3 + 1)} tool-calling rounds, not "
            f"{turns} - a tool round costs 3 steps, so {turns} turns need "
            f"{needed}. The step backstop will stop runs before the turn "
            "limit does."
        )

    def _loaded_tool_result_display_chars(self) -> int:
        # TASK-870: how much of an agent tool result the Console DISPLAYS --
        # distinct from [agents]/RunBudget.max_tool_result_chars, which
        # governs how much the MODEL saw and is not user-configurable here.
        return coerce_int_setting(
            self._console_settings().get(
                "tool_result_display_chars",
                DEFAULT_CONSOLE_TOOL_RESULT_DISPLAY_CHARS,
            ),
            DEFAULT_CONSOLE_TOOL_RESULT_DISPLAY_CHARS,
            minimum=MIN_CONSOLE_TOOL_RESULT_DISPLAY_CHARS,
            maximum=MAX_CONSOLE_TOOL_RESULT_DISPLAY_CHARS,
        )

    def _loaded_console_sidechat_model(self) -> str:
        # Side-chat phase 2 (task-2): empty string means "use the current
        # session's model" -- the fallback lives in the side-chat service.
        value = self._console_settings().get("sidechat_model", "")
        return value.strip() if isinstance(value, str) else ""

    def _loaded_console_sidechat_prompt_template(self) -> str:
        # Mirrors the loader's coercion (config.py): non-strings fall back
        # to the default; a blank string stays blank and the runtime side
        # chat falls back to the default template.
        value = self._console_settings().get(
            "sidechat_prompt_template", DEFAULT_CONSOLE_SIDECHAT_PROMPT_TEMPLATE
        )
        if not isinstance(value, str):
            return DEFAULT_CONSOLE_SIDECHAT_PROMPT_TEMPLATE
        return value.strip()

    @staticmethod
    def _coerce_float_default(
        value: object,
        fallback: float,
        *,
        minimum: float,
        maximum: float,
    ) -> float:
        if isinstance(value, bool):
            return fallback
        try:
            number = float(value)
        except (TypeError, ValueError):
            return fallback
        if minimum <= number <= maximum:
            return number
        return fallback

    def _loaded_console_default_streaming(self) -> bool:
        chat_defaults = self._chat_defaults()
        if "streaming" in chat_defaults:
            return coerce_bool_setting(chat_defaults.get("streaming"), True)
        if "enable_streaming" in chat_defaults:
            return coerce_bool_setting(chat_defaults.get("enable_streaming"), True)
        return True

