    # ------------------------------------------------------------------
    # Image Gen (task 5): draft/dirty editing + Save/Revert.
    #
    # Unlike APPEARANCE/LIBRARY_RAG/STORAGE (flat scalar fields), Image Gen
    # stages edits into `self._settings_drafts[IMAGE_GENERATION]` using
    # namespaced string keys so the ONE generic `SettingsDraft` still drives
    # the shared dirty-marker mechanism (`_category_has_unsaved_changes`,
    # the rail `*`, `settings-dirty-category`) -- no parallel draft
    # mechanism. Keys: "default_backend", "enabled_backends",
    # "context_llm_enabled", "default_batch", "max_variants_per_message",
    # "context_llm_turns", "context_llm_timeout_seconds",
    # "field::<backend_id>::<toml_key>" (per edited backend field), and
    # "cleared::<backend_id>::<toml_key>" (per Clear action).
    #
    # The diff/save baseline is ALWAYS `SettingsConfigAdapter().load()`'s
    # MERGED `[image_generation]` view -- never `load_user_image_generation_
    # table()`, which is display-only (see that helper's and
    # `diff_to_sections`'s docstrings). Using the merged view as the
    # "original" for dirty-tracking is what makes the Enabled checkboxes,
    # the default-backend Select, and `context_llm_enabled` safe to stage
    # straight from LIVE widget state on every change and at save time:
    # unlike free-text Inputs, Checkboxes/Select have no "blank value means
    # deferred to placeholder" ambiguity, and they're initialized from that
    # SAME merged config -- so an untouched widget's value always equals
    # its own "original" (never a spurious diff), while a genuinely toggled
    # one always differs.
    def _image_gen_raw_section(self) -> Mapping[str, object]:
        # Qodo PR #901 fix 3: cached per category session -- see
        # `_image_gen_raw_section_cache`'s docstring at its `__init__`
        # declaration for the exact three invalidation points.
        if self._image_gen_raw_section_cache is None:
            raw = SettingsConfigAdapter().load().get("image_generation")
            self._image_gen_raw_section_cache = raw if isinstance(raw, Mapping) else {}
        return self._image_gen_raw_section_cache

    def _image_gen_overlay_values(self) -> dict[str, object]:
        draft = self._settings_drafts.get(SettingsCategoryId.IMAGE_GENERATION)
        return dict(draft.values) if draft is not None else {}

    def _image_gen_expected_default_backend_select_value(
        self, overlay: Mapping[str, object]
    ) -> object:
        """The exact value `ImageGenSettingsPanel.compose()` is about to
        construct `#settings-imagegen-default_backend` with, for `overlay`
        -- must mirror that compose() logic exactly (see
        `_queue_image_gen_select_suppression`'s docstring)."""
        cfg = get_image_generation_config(reload=True)
        effective_default_backend = overlay.get("default_backend", cfg.default_backend)
        return (
            effective_default_backend
            if effective_default_backend in IMAGE_GEN_BACKEND_IDS
            else Select.NULL
        )

    def _queue_image_gen_select_suppression(
        self, overlay: Mapping[str, object]
    ) -> None:
        """Record the value the about-to-(re)compose default-backend
        `Select` will mount with, if that value is non-blank -- a fresh
        `Select` only posts `Changed` on mount when constructed with a
        non-`Select.NULL` value (verified empirically; unlike Checkbox,
        which never refires on construction regardless of value). Call
        this immediately before every `ImageGenSettingsPanel` (re)compose:
        the initial category-open `_render_detail_pane` branch, and the
        `panel.recompose()` calls in `_apply_image_gen_save_result` /
        `_handle_image_gen_revert`. See `_rag_select_suppress_queue` for
        the sibling idiom this mirrors (a boolean in-progress flag cannot
        suppress a deferred `Select.Changed` message)."""
        expected_value = self._image_gen_expected_default_backend_select_value(overlay)
        if expected_value is not Select.NULL:
            self._image_gen_select_suppress_queue.append(expected_value)

    def _image_gen_stage(self, key: str, original: object, value: object) -> None:
        category = SettingsCategoryId.IMAGE_GENERATION
        draft = self._settings_drafts.setdefault(
            category, SettingsDraft(category=category)
        )
        draft.set_value(key, original, value)
        if not draft.is_dirty:
            self._settings_drafts.pop(category, None)
        self._update_draft_status_widgets(category)

    def _image_gen_unstage(self, key: str) -> None:
        """Remove one staged key without touching any other (e.g. a fresh
        edit cancelling a pending Clear on the SAME field)."""
        category = SettingsCategoryId.IMAGE_GENERATION
        draft = self._settings_drafts.get(category)
        if draft is None:
            return
        draft.values.pop(key, None)
        draft.originals.pop(key, None)
        if not draft.is_dirty:
            self._settings_drafts.pop(category, None)

    def _stage_image_gen_field(
        self, backend_id: str, toml_key: str, raw_value: str
    ) -> None:
        raw_backend = self._image_gen_raw_section().get(backend_id) or {}
        original = (
            raw_backend.get(toml_key) if isinstance(raw_backend, Mapping) else None
        )
        original_str = "" if original is None else str(original)
        self._image_gen_stage(
            f"field::{backend_id}::{toml_key}", original_str, raw_value
        )
        # Typing into a field cancels a pending Clear on that SAME field --
        # otherwise diff_to_sections' documented "cleared wins" rule would
        # silently delete a key the user just retyped.
        self._image_gen_unstage(f"cleared::{backend_id}::{toml_key}")
        self._update_draft_status_widgets(SettingsCategoryId.IMAGE_GENERATION)

    @staticmethod
    def _image_gen_coerce_int(raw_value: str) -> int | None:
        try:
            return int(raw_value.strip())
        except ValueError:
            return None

    @staticmethod
    def _image_gen_coerce_float(raw_value: str) -> float | None:
        try:
            return float(raw_value.strip())
        except ValueError:
            return None

    def _refresh_image_gen_default_markers(
        self, effective_default_backend: str
    ) -> None:
        for backend_id in IMAGE_GEN_BACKEND_IDS:
            try:
                marker = self.query_one(
                    f"#settings-imagegen-default-marker-{backend_id}", Static
                )
            except QueryError:
                continue
            marker.update(
                "★ Default" if backend_id == effective_default_backend else ""
            )

    def _image_gen_draft_values_for_save(
        self, panel: ImageGenSettingsPanel
    ) -> ImageGenDraftValues:
        draft = self._settings_drafts.get(SettingsCategoryId.IMAGE_GENERATION)
        values = draft.values if draft is not None else {}
        backend_fields: dict[str, dict[str, str]] = {}
        cleared_fields: dict[str, list[str]] = {}
        for key, value in values.items():
            if key.startswith("field::"):
                _prefix, backend_id, toml_key = key.split("::", 2)
                backend_fields.setdefault(backend_id, {})[toml_key] = value
            elif key.startswith("cleared::"):
                _prefix, backend_id, toml_key = key.split("::", 2)
                cleared_fields.setdefault(backend_id, []).append(toml_key)

        # enabled_backends/default_backend/context_llm_enabled are ALWAYS
        # read live off the mounted widgets (never from `values`) -- see
        # the class-comment above for why this is safe and required (an
        # untouched checkbox/select must still be reflected, since it's
        # never staged unless the user actually toggles it).
        enabled_backends = [
            backend_id
            for backend_id in IMAGE_GEN_BACKEND_IDS
            if panel.query_one(
                f"#settings-imagegen-enabled-{backend_id}", Checkbox
            ).value
        ]
        default_backend_widget_value = panel.query_one(
            "#settings-imagegen-default_backend", Select
        ).value
        default_backend = (
            default_backend_widget_value
            if isinstance(default_backend_widget_value, str)
            else None
        )
        context_llm_enabled = bool(
            panel.query_one("#settings-imagegen-context_llm_enabled", Checkbox).value
        )

        return ImageGenDraftValues(
            default_backend=default_backend,
            enabled_backends=enabled_backends,
            default_batch=values.get("default_batch"),
            max_variants_per_message=values.get("max_variants_per_message"),
            context_llm_enabled=context_llm_enabled,
            context_llm_turns=values.get("context_llm_turns"),
            context_llm_timeout_seconds=values.get("context_llm_timeout_seconds"),
            backend_fields=backend_fields,
            cleared_fields=cleared_fields,
        )

    @on(Select.Changed, "#settings-imagegen-default_backend")
    def handle_image_gen_default_backend_changed(self, event: Select.Changed) -> None:
        event.stop()
        # A brand-new Select instance refires Changed with its OWN initial
        # value the moment it mounts (every category open + every post-
        # Save/Revert recompose) -- consume-and-ignore that expected
        # arrival rather than re-staging the value it's already showing as
        # a spurious "edit". See _queue_image_gen_select_suppression.
        queue = self._image_gen_select_suppress_queue
        if queue and event.value == queue[0]:
            queue.pop(0)
            return
        value = event.value if isinstance(event.value, str) else None
        if value is None:
            self._image_gen_unstage("default_backend")
            self._update_draft_status_widgets(SettingsCategoryId.IMAGE_GENERATION)
            # Qodo PR #901 fix 1: clearing the Select to blank must clear
            # every row's "★ Default" marker too -- left unrefreshed, the
            # OLD default's marker keeps showing, now inconsistent with
            # the Select itself showing nothing selected.
            self._refresh_image_gen_default_markers("")
            return
        original = self._image_gen_raw_section().get("default_backend")
        self._image_gen_stage("default_backend", original, value)
        self._refresh_image_gen_default_markers(value)

    @on(Checkbox.Changed)
    def handle_image_gen_checkbox_changed(self, event: Checkbox.Changed) -> None:
        checkbox_id = str(getattr(event.checkbox, "id", "") or "")
        if not checkbox_id.startswith("settings-imagegen-"):
            return
        event.stop()
        from ...Widgets.settings_image_gen_panel import switch_word, toggle_label

        if checkbox_id == "settings-imagegen-context_llm_enabled":
            event.checkbox.label = toggle_label("Context LLM", bool(event.value))
            original = bool(self._image_gen_raw_section().get("context_llm_enabled"))
            self._image_gen_stage("context_llm_enabled", original, bool(event.value))
            return
        prefix = "settings-imagegen-enabled-"
        if not checkbox_id.startswith(prefix):
            return
        event.checkbox.label = switch_word(bool(event.value))
        try:
            panel = self.query_one("#settings-imagegen-panel", ImageGenSettingsPanel)
        except QueryError:
            return
        enabled_backends = [
            backend_id
            for backend_id in IMAGE_GEN_BACKEND_IDS
            if panel.query_one(
                f"#settings-imagegen-enabled-{backend_id}", Checkbox
            ).value
        ]
        # Normalized to canonical order (Minor 1, final review) -- `enabled_
        # backends` is already canonical (built by iterating IMAGE_GEN_
        # BACKEND_IDS above); without normalizing `original` the SAME way,
        # a config file whose list happens to be in a different order would
        # spuriously stage a "dirty" edit even when nothing actually
        # changed, and the rail marker would never clear on its own.
        original = image_gen_canonical_backend_order(
            self._image_gen_raw_section().get("enabled_backends")
        )
        self._image_gen_stage("enabled_backends", original, enabled_backends)

    _IMAGE_GEN_INT_GLOBAL_KEYS = {
        "settings-imagegen-default_batch": "default_batch",
        "settings-imagegen-max_variants_per_message": "max_variants_per_message",
        "settings-imagegen-context_llm_turns": "context_llm_turns",
    }

    @on(Input.Changed)
    def handle_image_gen_input_changed(self, event: Input.Changed) -> None:
        input_id = str(getattr(event.input, "id", "") or "")
        if not input_id.startswith("settings-imagegen-"):
            return
        prefix = "settings-imagegen-field-"
        if input_id.startswith(prefix):
            event.stop()
            remainder = input_id[len(prefix) :]
            for backend_id in IMAGE_GEN_BACKEND_IDS:
                backend_prefix = f"{backend_id}-"
                if remainder.startswith(backend_prefix):
                    toml_key = remainder[len(backend_prefix) :]
                    self._stage_image_gen_field(backend_id, toml_key, event.value)
                    return
            return
        global_key = self._IMAGE_GEN_INT_GLOBAL_KEYS.get(input_id)
        if global_key is not None:
            event.stop()
            original = self._image_gen_raw_section().get(global_key)
            # An unparseable edit is staged as the raw string rather than
            # silently dropped -- it still marks dirty, and validate_draft
            # (settings_image_gen_defaults.py) is what actually catches it
            # at Save time with an inline error, matching the per-backend
            # "int"-kind fields' treatment exactly instead of the edit
            # just vanishing with no feedback at all.
            coerced = self._image_gen_coerce_int(event.value)
            staged_value = coerced if coerced is not None else event.value
            self._image_gen_stage(global_key, original, staged_value)
            return
        if input_id == "settings-imagegen-context_llm_timeout_seconds":
            event.stop()
            original = self._image_gen_raw_section().get("context_llm_timeout_seconds")
            coerced_float = self._image_gen_coerce_float(event.value)
            staged_value = coerced_float if coerced_float is not None else event.value
            self._image_gen_stage("context_llm_timeout_seconds", original, staged_value)

    def _handle_image_gen_clear(self, backend_id: str, toml_key: str) -> None:
        self._image_gen_stage(f"cleared::{backend_id}::{toml_key}", False, True)
        if backend_id == "swarmui" and toml_key == "swarm_token":
            # The loader also resolves the legacy `api_key` spelling as a
            # back-compat fallback; Clear must delete BOTH or a stale
            # hand-edited api_key resurrects the credential with no in-UI
            # recovery (deleting an absent key is a no-op, so this is free).
            self._image_gen_stage("cleared::swarmui::api_key", False, True)
        self._image_gen_unstage(f"field::{backend_id}::{toml_key}")
        new_source = image_gen_key_source_after_clear(backend_id)
        try:
            secret_input = self.query_one(
                f"#settings-imagegen-field-{backend_id}-{toml_key}", Input
            )
            secret_input.value = ""
            secret_input.placeholder = _image_gen_secret_placeholder(new_source)
        except QueryError:
            pass
        try:
            source_static = self.query_one(
                f"#settings-imagegen-key-source-{backend_id}", Static
            )
            source_static.update(_image_gen_key_source_line(new_source))
            secret_optional = backend_id == "swarmui"
            source_static.set_class(
                secret_optional and new_source == "missing",
                "settings-imagegen-key-source-neutral",
            )
        except QueryError:
            pass
        self._update_draft_status_widgets(SettingsCategoryId.IMAGE_GENERATION)

    # ------------------------------------------------------------------
    # Image Gen (task 6): backend "Test" probes.
    #
    # A probe never persists anything -- it's a short live/filesystem
    # reachability check (`probe_backend`, settings_image_gen_defaults.py)
    # run against the CURRENT (possibly-unsaved) form values for one
    # backend. `probe_backend` is BLOCKING (a plain HTTP GET or filesystem
    # stat), so it always runs off the UI thread via `@work(thread=True)`;
    # any exception it fails to catch itself degrades to a safe closed-set
    # badge here rather than ever propagating exception text into a badge
    # or a notify(). Only one probe may be in flight at a time
    # (`_image_gen_probe_in_flight` + all six Test buttons disabled
    # meanwhile) -- see `_image_gen_probe_session`'s docstring (near its
    # declaration) for how a stale callback from a since-left-and-
    # reentered category is safely dropped instead of clobbering an
    # unrelated, freshly (re)opened panel.

    def _image_gen_test_form_values(
        self, panel: ImageGenSettingsPanel, backend_id: str
    ) -> dict[str, str]:
        """Gather the CURRENT non-secret form values for `backend_id`'s Test
        probe -- an edited-but-unsaved Input wins; a blank (untouched)
        Input falls back to the resolved effective value it's currently
        showing as its own placeholder (see `effective_placeholder`),
        never a blank string `probe_backend` could mistake for
        "explicitly cleared"."""
        cfg = get_image_generation_config(reload=True)
        form_values: dict[str, str] = {}
        for spec in IMAGE_GEN_FIELD_SCHEMA[backend_id]:
            if spec.kind == "secret":
                continue
            try:
                current = panel.query_one(
                    f"#settings-imagegen-field-{backend_id}-{spec.toml_key}", Input
                ).value.strip()
            except QueryError:
                current = ""
            form_values[spec.toml_key] = current or image_gen_effective_placeholder(
                cfg, backend_id, spec.toml_key
            )
        return form_values

    def _image_gen_test_secret(
        self, panel: ImageGenSettingsPanel, backend_id: str
    ) -> str | None:
        """The secret to probe with: this session's pasted-but-unsaved
        value if present, else the effective resolved secret (env/config/
        keyring) -- see `probe_backend`'s `secret` parameter docstring."""
        secret_spec = next(
            (
                spec
                for spec in IMAGE_GEN_FIELD_SCHEMA[backend_id]
                if spec.kind == "secret"
            ),
            None,
        )
        if secret_spec is None:
            return None
        try:
            pasted = panel.query_one(
                f"#settings-imagegen-field-{backend_id}-{secret_spec.toml_key}", Input
            ).value.strip()
        except QueryError:
            pasted = ""
        if pasted:
            return pasted
        cfg = get_image_generation_config(reload=True)
        return image_gen_effective_secret_value(cfg, backend_id)

    def _image_gen_set_test_buttons_disabled(self, disabled: bool) -> None:
        for backend_id in IMAGE_GEN_BACKEND_IDS:
            try:
                self.query_one(
                    f"#settings-imagegen-test-{backend_id}", Button
                ).disabled = disabled
            except QueryError:
                continue

    def _handle_image_gen_test(self, backend_id: str) -> None:
        if self._image_gen_probe_in_flight:
            return
        try:
            panel = self.query_one("#settings-imagegen-panel", ImageGenSettingsPanel)
        except QueryError:
            return
        form_values = self._image_gen_test_form_values(panel, backend_id)
        secret = self._image_gen_test_secret(panel, backend_id)
        self._image_gen_probe_in_flight = True
        self._image_gen_set_test_buttons_disabled(True)
        self._image_gen_probe_worker(
            backend_id, form_values, secret, self._image_gen_probe_session
        )

    @work(thread=True, exclusive=False, exit_on_error=False)
    def _image_gen_probe_worker(
        self,
        backend_id: str,
        form_values: dict[str, str],
        secret: str | None,
        session: int,
    ) -> None:
        try:
            badge = image_gen_probe_backend(backend_id, form_values, secret).badge
        except Exception as exc:  # noqa: BLE001 - any escape must degrade safely
            # Qodo PR #901 fix 2: this probe builds Authorization headers
            # from a pasted-or-effective secret -- the spec's keys-never-
            # enter-logs contract forbids logging the raw exception text
            # (it could echo a header, URL, or secret embedded in some
            # library's error message). Log only the exception TYPE name
            # and the backend id, never str(exc).
            logger.debug(
                f"Image Gen probe for {backend_id!r} raised {type(exc).__name__}"
            )
            badge = "Unreachable: probe error"
        finally:
            self.app.call_from_thread(
                self._apply_image_gen_probe_result, backend_id, badge, session
            )

    def _apply_image_gen_probe_result(
        self, backend_id: str, badge: str, session: int
    ) -> None:
        if session != self._image_gen_probe_session:
            # Stale: the category was left (and possibly re-entered, minting
            # a brand-new panel) since this probe was dispatched. Dropping
            # it here -- rather than clearing `_image_gen_probe_in_flight`
            # or touching any widget -- is what keeps a leftover result from
            # a PREVIOUS visit from ever re-enabling buttons for (or
            # overwriting a badge on) an unrelated, currently active probe
            # or freshly (re)opened panel.
            return
        self._image_gen_probe_in_flight = False
        self._image_gen_set_test_buttons_disabled(False)
        try:
            self.query_one(f"#settings-imagegen-status-{backend_id}", Static).update(
                badge
            )
        except QueryError:
            pass

    def _handle_image_gen_save(self) -> None:
        try:
            panel = self.query_one("#settings-imagegen-panel", ImageGenSettingsPanel)
        except QueryError:
            return
        draft_values = self._image_gen_draft_values_for_save(panel)
        errors, warnings = validate_image_gen_draft(draft_values)
        if errors:
            message = " ".join(errors)
            self._set_static_text("#settings-imagegen-save-result", message)
            self.app.notify(message, severity="error")
            return
        self._set_static_text(
            "#settings-imagegen-save-result", "Saving Image Gen defaults..."
        )
        self._settings_save_image_gen_worker(draft_values, warnings)

    @work(exclusive=True, group="settings-save-image-gen", thread=True)
    def _settings_save_image_gen_worker(
        self, draft_values: ImageGenDraftValues, warnings: list[str]
    ) -> None:
        raw_config = SettingsConfigAdapter().load()
        sections, deletions = image_gen_diff_to_sections(draft_values, raw_config)
        mutation = apply_settings_mutation_to_cli_config(
            sections, delete_keys=deletions
        )
        if mutation.file_replaced:
            reset_image_generation_runtime()
        ok = mutation.failure_phase is None
        self.app.call_from_thread(self._apply_image_gen_save_result, ok, warnings)

    async def _apply_image_gen_save_result(
        self, saved: bool, warnings: list[str]
    ) -> None:
        if not saved:
            message = "Failed to save Image Gen defaults."
            self._set_static_text("#settings-imagegen-save-result", message)
            self.app.notify(message, severity="error")
            return
        self._settings_drafts.pop(SettingsCategoryId.IMAGE_GENERATION, None)
        # Qodo PR #901 fix 3: the save just changed the on-disk truth --
        # invalidate the cached raw-section baseline (see
        # `_image_gen_raw_section_cache`'s docstring).
        self._image_gen_raw_section_cache = None
        message = "Image Gen defaults saved."
        if warnings:
            message = f"{message} {' '.join(warnings)}"
        try:
            panel = self.query_one("#settings-imagegen-panel", ImageGenSettingsPanel)
        except QueryError:
            panel = None
        if panel is not None:
            panel.overlay = {}
            self._queue_image_gen_select_suppression({})
            await panel.recompose()
            self._set_static_text("#settings-imagegen-save-result", message)
            # A fresh panel mounts its Test buttons enabled by default; if a
            # probe is still in flight (Save clicked mid-probe), re-assert
            # the disabled state on the newly-mounted buttons rather than
            # letting them render as clickable while ignored.
            if self._image_gen_probe_in_flight:
                self._image_gen_set_test_buttons_disabled(True)
        self._update_draft_status_widgets(SettingsCategoryId.IMAGE_GENERATION)
        self.app.notify(message, severity="warning" if warnings else "information")

    async def _handle_image_gen_revert(self) -> None:
        self._settings_drafts.pop(SettingsCategoryId.IMAGE_GENERATION, None)
        # Qodo PR #901 fix 3: revert is the third of the exactly-three
        # invalidation points (see `_image_gen_raw_section_cache`'s
        # docstring) -- the file itself doesn't change on revert, but
        # this keeps the cache's lifetime scoped strictly to "since the
        # last time the draft was known-consistent with disk" rather
        # than silently spanning across a discard-and-restart edit.
        self._image_gen_raw_section_cache = None
        try:
            panel = self.query_one("#settings-imagegen-panel", ImageGenSettingsPanel)
        except QueryError:
            panel = None
        if panel is not None:
            panel.overlay = {}
            self._queue_image_gen_select_suppression({})
            await panel.recompose()
            self._set_static_text("#settings-imagegen-save-result", "")
            # See the matching comment in _apply_image_gen_save_result.
            if self._image_gen_probe_in_flight:
                self._image_gen_set_test_buttons_disabled(True)
        self._update_draft_status_widgets(SettingsCategoryId.IMAGE_GENERATION)

    @on(Button.Pressed)
    async def handle_image_gen_button_pressed(self, event: Button.Pressed) -> None:
        button_id = str(getattr(event.button, "id", "") or "")
        if button_id == "settings-imagegen-save":
            event.stop()
            self._handle_image_gen_save()
            return
        if button_id == "settings-imagegen-revert":
            event.stop()
            await self._handle_image_gen_revert()
            return
        test_prefix = "settings-imagegen-test-"
        if button_id.startswith(test_prefix):
            backend_id = button_id[len(test_prefix) :]
            if backend_id in IMAGE_GEN_BACKEND_IDS:
                event.stop()
                self._handle_image_gen_test(backend_id)
            return
        prefix = "settings-imagegen-clear-"
        if not button_id.startswith(prefix):
            return
        event.stop()
        remainder = button_id[len(prefix) :]
        for backend_id in IMAGE_GEN_BACKEND_IDS:
            backend_prefix = f"{backend_id}-"
            if remainder.startswith(backend_prefix):
                toml_key = remainder[len(backend_prefix) :]
                self._handle_image_gen_clear(backend_id, toml_key)
                return

    def _category_has_unsaved_changes(self, category: SettingsCategoryId) -> bool:
        draft = self._settings_drafts.get(category)
        return bool(draft and draft.is_dirty)

    # ------------------------------------------------------------------
    # Video Gen (task-3401.12): draft/dirty editing + Save/Revert, mirroring
    # the Image Gen block's idioms at video's smaller surface (3 backends,
    # 6 globals). Namespaced draft keys are identical in shape:
    # "default_backend", "enabled_backends", "retention",
    # "retention_ttl_hours", "max_store_mb", "confirm_cost_estimate",
    # "field::<backend_id>::<toml_key>", "cleared::<backend_id>::<toml_key>".

    def _video_gen_raw_section(self) -> Mapping[str, object]:
        # Lazily cached per edit session; invalidated on save/revert (the
        # same exactly-three-points rule as the image block's cache).
        cache = getattr(self, "_video_gen_raw_section_cache", None)
        if cache is None:
            raw = SettingsConfigAdapter().load().get("video_generation")
            cache = raw if isinstance(raw, Mapping) else {}
            self._video_gen_raw_section_cache = cache
        return cache

    def _video_gen_overlay_values(self) -> dict[str, object]:
        draft = self._settings_drafts.get(SettingsCategoryId.VIDEO_GENERATION)
        return dict(draft.values) if draft is not None else {}

    def _video_gen_select_suppress_queues(self) -> dict[str, list[object]]:
        """Per-Select FIFOs of mount-time ``Changed`` values still expected.

        Keyed by widget id: the panel composes two ``Select``s, and a value
        one of them is about to echo must never be mistaken for the other's
        (TASK-23191).
        """
        queues = getattr(self, "_video_gen_select_suppress_queue", None)
        if not isinstance(queues, dict):
            queues = {}
            self._video_gen_select_suppress_queue = queues
        return queues

    def _queue_video_gen_select_suppression(
        self, overlay: Mapping[str, object]
    ) -> None:
        """Record what EVERY about-to-(re)compose Video Gen Select will mount
        with -- a fresh Select refires Changed on mount with a non-blank
        value, and this category diffs against the RAW config table, so an
        unrecorded echo of a value that is merely the effective default
        reads as an edit (TASK-23191: retention did exactly that, and a
        never-touched fresh profile opened on "Unsaved changes").

        Call immediately before every ``VideoGenSettingsPanel`` (re)compose:
        the category-open ``_render_detail_pane`` branch, and the
        ``panel.recompose()`` calls in ``_apply_video_gen_save_result`` /
        ``_handle_video_gen_revert``. This is the image block's idiom,
        widened from its single Select to a per-Select mapping.
        """
        queues = self._video_gen_select_suppress_queues()
        expected = video_gen_expected_select_mount_values(
            get_video_generation_config(reload=True), overlay
        )
        for select_id, value in expected.items():
            queues.setdefault(select_id, []).append(value)

    def _consume_video_gen_select_mount_echo(
        self, select_id: str, value: object
    ) -> bool:
        """Whether ``value`` is the mount echo queued for ``select_id``.

        Consumes the expectation when it matches, so only the first echo is
        swallowed and every later ``Changed`` on that Select is a real edit.
        """
        queue = self._video_gen_select_suppress_queues().get(select_id)
        if queue and value == queue[0]:
            queue.pop(0)
            return True
        return False

    def _video_gen_stage(self, key: str, original: object, value: object) -> None:
        category = SettingsCategoryId.VIDEO_GENERATION
        draft = self._settings_drafts.setdefault(
            category, SettingsDraft(category=category)
        )
        draft.set_value(key, original, value)
        if not draft.is_dirty:
            self._settings_drafts.pop(category, None)
        self._update_draft_status_widgets(category)

    def _video_gen_unstage(self, key: str) -> None:
        """Remove one staged key without touching any other."""
        category = SettingsCategoryId.VIDEO_GENERATION
        draft = self._settings_drafts.get(category)
        if draft is None:
            return
        draft.values.pop(key, None)
        draft.originals.pop(key, None)
        if not draft.is_dirty:
            self._settings_drafts.pop(category, None)

    def _stage_video_gen_field(
        self, backend_id: str, toml_key: str, raw_value: str
    ) -> None:
        raw_backend = self._video_gen_raw_section().get(backend_id) or {}
        original = (
            raw_backend.get(toml_key) if isinstance(raw_backend, Mapping) else None
        )
        original_str = "" if original is None else str(original)
        self._video_gen_stage(
            f"field::{backend_id}::{toml_key}", original_str, raw_value
        )
        # Typing into a field cancels a pending Clear on that SAME field.
        self._video_gen_unstage(f"cleared::{backend_id}::{toml_key}")
        self._update_draft_status_widgets(SettingsCategoryId.VIDEO_GENERATION)

    def _refresh_video_gen_default_markers(
        self, effective_default_backend: str
    ) -> None:
        for backend_id in VIDEO_GEN_BACKEND_IDS:
            try:
                marker = self.query_one(
                    f"#settings-videogen-default-marker-{backend_id}", Static
                )
            except QueryError:
                continue
            marker.update(
                "★ Default" if backend_id == effective_default_backend else ""
            )

    def _video_gen_draft_values_for_save(
        self, panel: VideoGenSettingsPanel
    ) -> VideoGenDraftValues:
        draft = self._settings_drafts.get(SettingsCategoryId.VIDEO_GENERATION)
        values = draft.values if draft is not None else {}
        backend_fields: dict = {}
        cleared_fields: dict[str, list[str]] = {}
        for key, value in values.items():
            if key.startswith("field::"):
                _prefix, backend_id, toml_key = key.split("::", 2)
                backend_fields.setdefault(backend_id, {})[toml_key] = value
            elif key.startswith("cleared::"):
                _prefix, backend_id, toml_key = key.split("::", 2)
                cleared_fields.setdefault(backend_id, []).append(toml_key)

        # Checkbox/Select values are ALWAYS read live (no blank ambiguity --
        # the image block's rule), so an untouched toggle still lands.
        enabled_backends = [
            backend_id
            for backend_id in VIDEO_GEN_BACKEND_IDS
            if panel.query_one(
                f"#settings-videogen-enabled-{backend_id}", Checkbox
            ).value
        ]
        default_backend_widget_value = panel.query_one(
            "#settings-videogen-default_backend", Select
        ).value
        default_backend = (
            default_backend_widget_value
            if isinstance(default_backend_widget_value, str)
            else None
        )
        retention_widget_value = panel.query_one(
            "#settings-videogen-retention", Select
        ).value
        retention = (
            retention_widget_value if isinstance(retention_widget_value, str) else None
        )
        confirm_cost_estimate = bool(
            panel.query_one("#settings-videogen-confirm_cost_estimate", Checkbox).value
        )
        # bool-kind backend fields (e.g. minimax allow_uploads) read live too.
        from .settings_video_gen_defaults import FIELD_SCHEMA as VIDEO_GEN_FIELD_SCHEMA

        for backend_id in VIDEO_GEN_BACKEND_IDS:
            for spec in VIDEO_GEN_FIELD_SCHEMA.get(backend_id, ()):
                if spec.kind != "bool":
                    continue
                try:
                    value = panel.query_one(
                        f"#settings-videogen-field-{backend_id}-{spec.toml_key}",
                        Checkbox,
                    ).value
                except QueryError:
                    continue
                backend_fields.setdefault(backend_id, {})[spec.toml_key] = bool(value)

        return VideoGenDraftValues(
            default_backend=default_backend,
            enabled_backends=enabled_backends,
            retention=retention,
            retention_ttl_hours=values.get("retention_ttl_hours"),
            max_store_mb=values.get("max_store_mb"),
            confirm_cost_estimate=confirm_cost_estimate,
            backend_fields=backend_fields,
            cleared_fields=cleared_fields,
        )

    @on(Select.Changed, "#settings-videogen-default_backend")
    def handle_video_gen_default_backend_changed(self, event: Select.Changed) -> None:
        event.stop()
        if self._consume_video_gen_select_mount_echo(
            VIDEO_GEN_DEFAULT_BACKEND_SELECT_ID, event.value
        ):
            return
        value = event.value if isinstance(event.value, str) else None
        original = self._video_gen_raw_section().get("default_backend")
        self._video_gen_stage("default_backend", original, value)
        if value is not None:
            self._refresh_video_gen_default_markers(value)

    @on(Select.Changed, "#settings-videogen-retention")
    def handle_video_gen_retention_changed(self, event: Select.Changed) -> None:
        event.stop()
        if self._consume_video_gen_select_mount_echo(
            VIDEO_GEN_RETENTION_SELECT_ID, event.value
        ):
            return
        value = event.value if isinstance(event.value, str) else None
        original = self._video_gen_raw_section().get("retention")
        self._video_gen_stage("retention", original, value)

    @on(Checkbox.Changed)
    def handle_video_gen_checkbox_changed(self, event: Checkbox.Changed) -> None:
        checkbox_id = str(getattr(event.checkbox, "id", "") or "")
        if not checkbox_id.startswith("settings-videogen-"):
            return
        event.stop()
        if checkbox_id == "settings-videogen-confirm_cost_estimate":
            original = self._video_gen_raw_section().get("confirm_cost_estimate")
            self._video_gen_stage("confirm_cost_estimate", original, bool(event.value))
            return
        prefix = "settings-videogen-enabled-"
        if checkbox_id.startswith(prefix):
            backend_id = checkbox_id[len(prefix) :]
            if backend_id not in VIDEO_GEN_BACKEND_IDS:
                return
            try:
                panel = self.query_one(
                    "#settings-videogen-panel", VideoGenSettingsPanel
                )
            except QueryError:
                return
            enabled_backends = [
                bid
                for bid in VIDEO_GEN_BACKEND_IDS
                if panel.query_one(f"#settings-videogen-enabled-{bid}", Checkbox).value
            ]
            checkbox = panel.query_one(
                f"#settings-videogen-enabled-{backend_id}", Checkbox
            )
            checkbox.label = "On" if checkbox.value else "Off"
            original = self._video_gen_raw_section().get("enabled_backends")
            self._video_gen_stage("enabled_backends", original, enabled_backends)
            return
        # bool-kind backend field (e.g. minimax allow_uploads)
        field_prefix = "settings-videogen-field-"
        if checkbox_id.startswith(field_prefix):
            remainder = checkbox_id[len(field_prefix) :]
            for backend_id in VIDEO_GEN_BACKEND_IDS:
                backend_prefix = f"{backend_id}-"
                if remainder.startswith(backend_prefix):
                    toml_key = remainder[len(backend_prefix) :]
                    raw_backend = self._video_gen_raw_section().get(backend_id) or {}
                    original = (
                        raw_backend.get(toml_key)
                        if isinstance(raw_backend, Mapping)
                        else None
                    )
                    self._video_gen_stage(
                        f"field::{backend_id}::{toml_key}", original, bool(event.value)
                    )
                    event.checkbox.label = (
                        f"{'Allow image uploads (i2v)'}: {'on' if event.value else 'off'}"
                        if toml_key == "allow_uploads"
                        else event.checkbox.label
                    )
                    return

    @on(Input.Changed)
    def handle_video_gen_input_changed(self, event: Input.Changed) -> None:
        input_id = str(getattr(event.input, "id", "") or "")
        if not input_id.startswith("settings-videogen-"):
            return
        event.stop()
        global_keys = {
            "settings-videogen-retention_ttl_hours": "retention_ttl_hours",
            "settings-videogen-max_store_mb": "max_store_mb",
        }
        if input_id in global_keys:
            key = global_keys[input_id]
            original = self._video_gen_raw_section().get(key)
            original_str = "" if original is None else str(original)
            self._video_gen_stage(key, original_str, event.value)
            return
        prefix = "settings-videogen-field-"
        if not input_id.startswith(prefix):
            return
        remainder = input_id[len(prefix) :]
        for backend_id in VIDEO_GEN_BACKEND_IDS:
            backend_prefix = f"{backend_id}-"
            if remainder.startswith(backend_prefix):
                toml_key = remainder[len(backend_prefix) :]
                self._stage_video_gen_field(backend_id, toml_key, event.value)
                return

    def _handle_video_gen_clear(self, backend_id: str, toml_key: str) -> None:
        """Stage an explicit Clear of a backend's locally-saved field."""
        self._video_gen_unstage(f"field::{backend_id}::{toml_key}")
        self._video_gen_stage(f"cleared::{backend_id}::{toml_key}", False, True)
        try:
            field_input = self.query_one(
                f"#settings-videogen-field-{backend_id}-{toml_key}", Input
            )
            field_input.value = ""
        except QueryError:
            pass
        try:
            source_line = self.query_one(
                f"#settings-videogen-key-source-{backend_id}", Static
            )
            from .settings_video_gen_defaults import key_source_after_clear

            source_line.update(key_source_after_clear(backend_id))
        except QueryError:
            pass
        self._update_draft_status_widgets(SettingsCategoryId.VIDEO_GENERATION)

    def _handle_video_gen_save(self) -> None:
        try:
            panel = self.query_one("#settings-videogen-panel", VideoGenSettingsPanel)
        except QueryError:
            return
        draft_values = self._video_gen_draft_values_for_save(panel)
        errors, warnings = validate_video_gen_draft(draft_values)
        if errors:
            message = " ".join(errors)
            self._set_static_text("#settings-videogen-save-result", message)
            self.app.notify(message, severity="error")
            return
        self._set_static_text(
            "#settings-videogen-save-result", "Saving Video Gen defaults..."
        )
        self._settings_save_video_gen_worker(draft_values, warnings)

    @work(exclusive=True, group="settings-save-video-gen", thread=True)
    def _settings_save_video_gen_worker(
        self, draft_values: VideoGenDraftValues, warnings: list[str]
    ) -> None:
        raw_config = SettingsConfigAdapter().load()
        sections, deletions = video_gen_diff_to_sections(draft_values, raw_config)
        adapter = SettingsConfigAdapter()
        ok = True
        if sections:
            ok = adapter.save_sections(sections) and ok
        for section, keys in deletions.items():
            if keys:
                ok = adapter.delete_values(section, keys) and ok
        if ok:
            reset_video_generation_runtime()
        self.app.call_from_thread(self._apply_video_gen_save_result, ok, warnings)

    async def _apply_video_gen_save_result(
        self, saved: bool, warnings: list[str]
    ) -> None:
        if not saved:
            message = "Failed to save Video Gen defaults."
            self._set_static_text("#settings-videogen-save-result", message)
            self.app.notify(message, severity="error")
            return
        self._settings_drafts.pop(SettingsCategoryId.VIDEO_GENERATION, None)
        self._video_gen_raw_section_cache = None
        message = "Video Gen defaults saved."
        if warnings:
            message = f"{message} {' '.join(warnings)}"
        try:
            panel = self.query_one("#settings-videogen-panel", VideoGenSettingsPanel)
        except QueryError:
            panel = None
        if panel is not None:
            panel.overlay = {}
            self._queue_video_gen_select_suppression({})
            await panel.recompose()
            self._set_static_text("#settings-videogen-save-result", message)
        self._update_draft_status_widgets(SettingsCategoryId.VIDEO_GENERATION)
        self.app.notify(message, severity="warning" if warnings else "information")

    async def _handle_video_gen_revert(self) -> None:
        self._settings_drafts.pop(SettingsCategoryId.VIDEO_GENERATION, None)
        self._video_gen_raw_section_cache = None
        try:
            panel = self.query_one("#settings-videogen-panel", VideoGenSettingsPanel)
        except QueryError:
            panel = None
        if panel is not None:
            panel.overlay = {}
            self._queue_video_gen_select_suppression({})
            await panel.recompose()
            self._set_static_text("#settings-videogen-save-result", "")
        self._update_draft_status_widgets(SettingsCategoryId.VIDEO_GENERATION)

    @on(Button.Pressed)
    async def handle_video_gen_button_pressed(self, event: Button.Pressed) -> None:
        button_id = str(getattr(event.button, "id", "") or "")
        if not button_id.startswith("settings-videogen-"):
            return
        event.stop()
        if button_id == "settings-videogen-save":
            self._handle_video_gen_save()
            return
        if button_id == "settings-videogen-revert":
            await self._handle_video_gen_revert()
            return
        prefix = "settings-videogen-clear-"
        if not button_id.startswith(prefix):
            return
        remainder = button_id[len(prefix) :]
        for backend_id in VIDEO_GEN_BACKEND_IDS:
            backend_prefix = f"{backend_id}-"
            if remainder.startswith(backend_prefix):
                toml_key = remainder[len(backend_prefix) :]
                self._handle_video_gen_clear(backend_id, toml_key)
                return

    def _guided_action_message(self, category: SettingsCategoryId) -> str:
        if category is SettingsCategoryId.APPEARANCE:
            if self._category_has_unsaved_changes(category):
                validation = self._appearance_validation_result()
                if not validation.valid:
                    return f"Guided edits: {validation.message}"
                return "Guided edits: Preview, Save, or Revert Appearance defaults."
            return "Guided edits: change an Appearance default first."
        if category is SettingsCategoryId.LIBRARY_RAG:
            if self._category_has_unsaved_changes(category):
                validation = self._library_rag_validation_result()
                if not validation.valid:
                    return f"Guided edits: {validation.message}"
                return "Guided edits: Save or Revert Library/RAG defaults."
            return "Guided edits: change a Library/RAG default first."
        if category == SettingsCategoryId.THEME:
            return "Use the editor's Apply/Save/Reset buttons to manage themes."
        if category == SettingsCategoryId.SPLASH_SCREEN:
            return f"Splash defaults: {INSTANT_APPLY_BEHAVIOR_COPY}."
        if category == SettingsCategoryId.WORKSPACES:
            return (
                "Immediate actions: workspace changes apply as you make them; "
                "there is no draft to save or revert."
            )
        if category == SettingsCategoryId.AGENTS:
            return (
                "Applies immediately: agent definitions save/delete as you "
                "act; there is no draft to save or revert."
            )
        if category is SettingsCategoryId.NETWORK:
            return (
                "Save with s: the TLS trust setting applies to newly created "
                "clients; already-open connections keep their trust policy "
                "until restart."
            )
        if category == SettingsCategoryId.INTERNAL_PROMPTS:
            return "Use each prompt's Save / Reset buttons in the editor to manage overrides."
        if category is SettingsCategoryId.SCHEDULES:
            return "Applies immediately: use the global briefing-schedules control below."
        if category == SettingsCategoryId.IMAGE_GENERATION:
            if self._category_has_unsaved_changes(category):
                return "Guided edits: use the panel's own Save/Revert controls below."
            return "Guided edits: change a backend or generation default first."
        if category is SettingsCategoryId.STORAGE:
            if self._category_has_unsaved_changes(category):
                validation = self._storage_validation_result()
                if not validation.valid:
                    return f"Guided edits: {validation.message}"
                return "Guided edits: Save or Revert Storage defaults."
            return "Guided edits: change a Storage default first."
        if category is SettingsCategoryId.PRIVACY_SECURITY:
            if self._category_has_unsaved_changes(category):
                return "Guided edit: Save or Revert the raw CLI unlock."
            return "Guided edit: raw CLI unlock only; posture remains read-only."
        if category in GUIDED_SETTINGS_MUTATION_CATEGORIES:
            if self._category_has_unsaved_changes(category):
                return "Guided edits: Save or Revert changes."
            return "Guided edits: change a field first."
        messages = {
            SettingsCategoryId.OVERVIEW: "Guided edits: choose Providers or Console.",
            SettingsCategoryId.DIAGNOSTICS: "Guided edits: use Validate/Reload.",
            SettingsCategoryId.ABOUT: "Guided edits: read-only; links open in browser.",
            SettingsCategoryId.ADVANCED_CONFIG: "Guided edits: use Raw TOML controls.",
        }
        if category in DOMAIN_SETTINGS_CATEGORY_IDS:
            contract = self._domain_category_contract(category)
            return f"Guided edits: read-only here; open {contract.owner_destination}."
        return messages.get(category, "Guided edits: read-only.")

    def _guided_actions_enabled(self, category: SettingsCategoryId) -> bool:
        if category is SettingsCategoryId.APPEARANCE:
            return self._appearance_save_enabled()
        if category is SettingsCategoryId.LIBRARY_RAG:
            return self._library_rag_save_enabled()
        if category is SettingsCategoryId.STORAGE:
            return self._storage_save_enabled()
        return (
            category in GUIDED_SETTINGS_MUTATION_CATEGORIES
            and self._category_has_unsaved_changes(category)
        )

    @staticmethod
    def _guided_action_label(base: str, *, dirty: bool) -> str:
        """Save/Revert label with a text-carried inert-state annotation.

        Disabled buttons differed from enabled ones only by dimming
        (task-1582); in the clean state the label itself says why the pair
        is inert. A dirty-but-invalid draft keeps the plain label -- the
        guided-action state row explains the validation block there.

        Args:
            base: The plain label, e.g. "Save (s)".
            dirty: Whether the active category has unsaved changes.

        Returns:
            The plain label when dirty, otherwise the annotated form.
        """
        return base if dirty else f"{base} — no changes"

    def _update_guided_action_widgets(self) -> None:
        category = self._active_category_id()
        actions_enabled = self._guided_actions_enabled(category)
        dirty = self._category_has_unsaved_changes(category)
        self._set_static_text(
            "#settings-guided-action-state", self._guided_action_message(category)
        )
        for selector, base in (
            ("#settings-save-category", "Save (s)"),
            ("#settings-revert-category", "Revert (r)"),
        ):
            try:
                button = self.query_one(selector, Button)
            except QueryError:
                continue
            button.disabled = not actions_enabled
            button.label = self._guided_action_label(base, dirty=dirty)

    def _category_status(self, summary: SettingsCategorySummary) -> str:
        if self._category_has_unsaved_changes(summary.category):
            return "Unsaved"
        return summary.status

    def _category_button_label(
        self,
        summary: SettingsCategorySummary,
        *,
        is_active: bool | None = None,
    ) -> str:
        active = (
            summary.category.value == self.active_category
            if is_active is None
            else is_active
        )
        dirty_marker = ""
        if self._category_has_unsaved_changes(summary.category):
            dirty_marker = " *"
        elif (
            summary.category == SettingsCategoryId.THEME and self.theme_editor_modified
        ):
            dirty_marker = " *"
        # task-1563: view-only stub categories are full nav peers whose whole
        # page says "edit elsewhere" -- badge them in the rail so a third of
        # the navigation stops masquerading as editable surface.
        view_marker = ""
        try:
            if not self._ownership_record(summary.category).writes_allowed:
                view_marker = " (view)"
        except Exception:
            view_marker = ""
        return f"{'> ' if active else '  '}{summary.title}{view_marker}{dirty_marker}"

    def _refresh_category_button_label(self, category: SettingsCategoryId) -> None:
        try:
            summary = self._category_summary_by_id(category)
            button = self.query_one(f"#settings-category-{category.value}", Button)
        except QueryError:
            return
        button.label = self._category_button_label(summary)

    def _active_category_id(self) -> SettingsCategoryId:
        return SettingsCategoryId(self.active_category)

    def _update_draft_status_widgets(self, category: SettingsCategoryId) -> None:
        has_unsaved_changes = self._category_has_unsaved_changes(category)
        status = "Unsaved changes" if has_unsaved_changes else "No unsaved changes"
        try:
            self.query_one("#settings-selected-category-draft-status", Static).update(
                status
            )
        except QueryError:
            pass
        self._update_category_state_banner(category)
        self._refresh_category_button_label(category)
        if category is self._active_category_id():
            self._update_guided_action_widgets()
        if category is SettingsCategoryId.IMAGE_GENERATION:
            # Image Gen's Save/Revert live INSIDE the panel (not the generic
            # top guided-action bar, excluded above like THEME/INTERNAL_
            # PROMPTS) -- toggle them here so every staging path updates
            # them through this one shared draft-status refresh, matching
            # the sibling idiom rather than a parallel mechanism.
            for button_id in ("settings-imagegen-save", "settings-imagegen-revert"):
                try:
                    self.query_one(
                        f"#{button_id}", Button
                    ).disabled = not has_unsaved_changes
                except QueryError:
                    pass
        if category is SettingsCategoryId.VIDEO_GENERATION:
            # task-3401.12: same sibling idiom for Video Gen's in-panel
            # Save/Revert.
            for button_id in ("settings-videogen-save", "settings-videogen-revert"):
                try:
                    self.query_one(
                        f"#{button_id}", Button
                    ).disabled = not has_unsaved_changes
                except QueryError:
                    pass

    def _category_summary_by_id(
        self, category: SettingsCategoryId
    ) -> SettingsCategorySummary:
        for summary in self._category_summaries():
            if summary.category is category:
                return summary
        return self._category_summaries()[0]

    def _sanitize_category_search_query(self, query_text: str | None) -> str:
        raw_query = "" if query_text is None else str(query_text)
        sanitized_query = sanitize_string(
            raw_query,
            max_length=MAX_CATEGORY_SEARCH_QUERY_CHARS,
        )
        if validate_text_input(
            sanitized_query,
            max_length=MAX_CATEGORY_SEARCH_QUERY_CHARS,
            allow_html=False,
        ):
            return sanitized_query
        return ""

    def _category_search_text(self, query_text: str | None = None) -> str:
        raw_query = self.category_search_query if query_text is None else query_text
        return raw_query.strip() if isinstance(raw_query, str) else ""

    def _category_search_rank(
        self,
        summary: SettingsCategorySummary,
        query_text: str | None = None,
    ) -> int | None:
        query = self._category_search_text(query_text).lower()
        if not query:
            return 0
        primary_haystack = " ".join((summary.category.value, summary.title)).lower()
        if query in primary_haystack:
            # task-1584: a match starting at a word boundary outranks a
            # mid-word substring hit -- "rag" must surface Library/RAG
            # before Storage (sto-RAG-e), which previously tied on tier
            # and won on list index.
            if re.search(rf"(?<![a-z0-9]){re.escape(query)}", primary_haystack):
                return 0
            return 1
        secondary_haystack = " ".join(
            (
                summary.description,
                self._category_status(summary),
            )
        ).lower()
        if query in secondary_haystack:
            return 2
        # task-1715: field labels -- typing a setting's visible name
        # ("threshold") surfaces its category with an Enter-focuses-field
        # promise (see _top_field_match / _submit_category_search).
        # TASK-23109: two field tiers -- a category with a label that STARTS
        # with the query ("Threshold (chars)") outranks one with only a
        # mid-label hit ("VAD threshold"), so completing the index cannot
        # re-route an established CROSS-category landing. The tier scans all
        # of the category's labels; WHICH field wins within the category
        # stays order-stable (_top_field_match), preserving pre-existing
        # intra-category landings (review finding 13: "/token" must keep
        # landing on "Conversation max tokens", not the swept-in
        # "Token budget (per run)").
        tier = self._field_match_rank_tier(query, summary.category)
        if tier is not None:
            return tier
        # task-1564: last tier -- the category's owned config keys. The Scope
        # Inspector already publishes them; indexing them lets "/" find the
        # category that OWNS a setting instead of forcing a 23-item scan.
        try:
            owned = " ".join(
                self._ownership_record(summary.category).owns_config_sections
            ).lower()
        except Exception:
            owned = ""
        if owned and query in owned:
            return 5
        return None

    #: Ranks meaning the query matched the category's own name -- Enter on
    #: these opens the category plainly, never a coincidental field
    #: (review finding 2: description-tier matches such as "context window"
    #: on Providers & Models DO land on their matching field).
    TITLE_MATCH_RANKS = frozenset({0, 1})

    @staticmethod
    def _field_match_rank_tier(
        query_text: str, category: SettingsCategoryId
    ) -> int | None:
        """Field-tier rank for a category: 3 (label-prefix), 4 (contains).

        Scans every indexed label so the CATEGORY ranking can prefer a
        prefix hit anywhere in the category, independent of which field
        ``_top_field_match`` (order-stable) actually lands on.
        """
        query = query_text.strip().lower()
        if not query:
            return None
        entries = FIELD_SEARCH_INDEX.get(category, ())
        if any(label.lower().startswith(query) for _fid, label in entries):
            return 3
        if any(query in label.lower() for _fid, label in entries):
            return 4
        return None

    @staticmethod
    def _top_field_match(
        query_text: str, category: SettingsCategoryId
    ) -> tuple[str, str] | None:
        """First indexed field of ``category`` whose label matches the query.

        Args:
            query_text: The lowercased-or-raw filter text.
            category: The category whose field index to search.

        Returns:
            ``(field_id, label)`` for the first matching field, or None.
        """
        query = query_text.strip().lower()
        if not query:
            return None
        # Order-stable single pass (review finding 13): the first containment
        # hit in index order wins WITHIN a category, so completing the index
        # (rows are appended) cannot re-route established landings. Prefix
        # quality only affects CROSS-category ranking -- see
        # _field_match_rank_tier.
        for field_id, label in FIELD_SEARCH_INDEX.get(category, ()):
            if query in label.lower():
                return (field_id, label)
        return None

    def _category_matches_search(
        self,
        summary: SettingsCategorySummary,
        query_text: str | None = None,
    ) -> bool:
        return self._category_search_rank(summary, query_text) is not None

    def _filtered_category_summaries(
        self,
        query_text: str | None = None,
    ) -> tuple[SettingsCategorySummary, ...]:
        ranked_summaries: list[tuple[int, int, SettingsCategorySummary]] = []
        for index, summary in enumerate(self._category_summaries()):
            rank = self._category_search_rank(summary, query_text)
            if rank is not None:
                ranked_summaries.append((rank, index, summary))
        return tuple(summary for _, _, summary in sorted(ranked_summaries))

    def _filtered_category_values(self, query_text: str | None = None) -> list[str]:
        return [
            summary.category.value
            for summary in self._filtered_category_summaries(query_text)
        ]

    def _category_group_title(self, category: SettingsCategoryId) -> str:
        """The rail group a category lives in ("Core", "Interface", ...)."""
        for group_title, category_ids in self._category_groups():
            if category in category_ids:
                return group_title
        return ""

    def _search_match_scope_text(
        self,
        query: str,
        summary: SettingsCategorySummary,
        *,
        field_landing: bool,
    ) -> str:
        """One search match with its scope: 'Category [› Field] (Group)'.

        TASK-23109: ambiguous matches ("theme" hits both the Theme category
        and Appearance's Theme setting) disambiguate with the category and
        rail-group scope instead of a bare title coin flip.

        Args:
            query: The active filter text.
            summary: The matched category.
            field_landing: Whether Enter would land ON the matched field
                if this match were opened -- compute it with
                ``_search_match_is_field_landing`` so the echo line and the
                Enter behavior state the same contract (typing a category's
                own title opens the category plainly, every other tier with
                a matching field lands on it).
        """
        target = summary.title
        # task-1715: when the hit is (or contains) a matching field, promise
        # the field-level landing in the echo line.
        field = self._top_field_match(query, summary.category)
        if field is not None and field_landing:
            target = f"{target} › {field[1]}"
        group = self._category_group_title(summary.category)
        return f"{target} ({group})" if group else target

    def _search_match_is_field_landing(
        self, query: str, summary: SettingsCategorySummary
    ) -> bool:
        """Whether Enter on this top match lands focus on a matched field.

        Review finding 2: only own-TITLE matches suppress the landing --
        a description-tier match ("context window" on Providers & Models)
        with a matching field still lands on that field, as task-1715 did.
        """
        rank = self._category_search_rank(summary, query)
        if rank is None or rank in self.TITLE_MATCH_RANKS:
            return False
        return self._top_field_match(query, summary.category) is not None

    #: Below this screen height the "| Next:" disambiguation segment is
    #: dropped: in the 30-col rail the full scoped line wraps to ~5 rows,
    #: which on a 24-row terminal pushed most matched category rows below
    #: the fold mid-search (review finding 15, verified at 110x24 with a
    #: 16-match query leaving 6 rail rows visible).
    SEARCH_STATUS_NEXT_MIN_HEIGHT = 30

    def _suppress_search_next_segment(self) -> bool:
        """Whether the rail is too short to spend rows on '| Next:'."""
        try:
            height = int(self.size.height)
        except Exception:
            height = 0
        return 0 < height < self.SEARCH_STATUS_NEXT_MIN_HEIGHT

    def _category_search_status_text(self, query_text: str | None = None) -> str:
        query = self._category_search_text(query_text)
        if not query:
            return "No filter | / focus category search"
        matches = self._filtered_category_summaries(query)
        match_label = "match" if len(matches) == 1 else "matches"
        if matches:
            target = self._search_match_scope_text(
                query,
                matches[0],
                field_landing=self._search_match_is_field_landing(query, matches[0]),
            )
            status = (
                f"Filter: {query} | {len(matches)} {match_label} | Enter opens {target}"
            )
            if len(matches) > 1 and not self._suppress_search_next_segment():
                # Review finding 10: the Next segment states the SAME
                # landing contract Enter would honour if this match were
                # first -- never advertise a field landing the gate refuses.
                status += (
                    " | Next: "
                    + self._search_match_scope_text(
                        query,
                        matches[1],
                        field_landing=self._search_match_is_field_landing(
                            query, matches[1]
                        ),
                    )
                )
            return status
        return f"Filter: {query} | 0 matches | Esc clears"

    @staticmethod
    def _category_group_dom_id(group_title: str) -> str:
        return f"settings-category-group-{group_title.lower().replace(' ', '-').replace('&', 'and')}"

    def _apply_category_search_filter(self) -> None:
        summaries_by_id = {
            summary.category: summary for summary in self._category_summaries()
        }
        visible_count = 0
        query = self._category_search_text()
        for group_title, category_ids in self._category_groups():
            group_visible = False
            is_domain_group = group_title == self.DOMAIN_DEFAULTS_GROUP_TITLE
            group_expanded = (
                not is_domain_group or bool(query) or self._domain_group_is_expanded()
            )
            for category_id in category_ids:
                summary = summaries_by_id[category_id]
                rank = self._category_search_rank(summary)
                matches = rank is not None
                group_visible = group_visible or matches
                is_visible = matches and group_expanded
                visible_count += int(is_visible)
                try:
                    button = self.query_one(
                        f"#settings-category-{summary.category.value}", Button
                    )
                    button.display = is_visible
                    button.remove_class("settings-primary-search-match")
                    button.remove_class("settings-secondary-search-match")
                    # task-1584 rescaled tiers: 0/1 are both primary
                    # (word-boundary vs substring); 2 is description/status.
                    if query and rank in (0, 1):
                        button.add_class("settings-primary-search-match")
                    elif query and rank == 2:
                        button.add_class("settings-secondary-search-match")
                except QueryError:
                    pass
            try:
                group_heading = self.query_one(
                    f"#{self._category_group_dom_id(group_title)}"
                )
                group_heading.display = group_visible
                if is_domain_group and isinstance(group_heading, Button):
                    group_heading.label = self._domain_group_toggle_label()
            except QueryError:
                pass

        try:
            status = self.query_one("#settings-category-search-status", Static)
            status.update(self._category_search_status_text())
        except QueryError:
            pass
        try:
            search = self.query_one("#settings-category-search", Input)
            search.set_class(bool(query), "settings-category-search-active")
        except QueryError:
            pass
        try:
            empty_state = self.query_one("#settings-category-search-empty", Static)
        except QueryError:
            return
        empty_state.update(f"No Settings categories match: {query}")
        empty_state.display = bool(query and visible_count == 0)

    @staticmethod
    def _speech_tts_provider_from_search(query_text: str) -> str | None:
        """Return a canonical built-in TTS provider named by a search query."""
        query = query_text.strip().lower()
        aliases = {
            "audio.cpp": "audio_cpp",
            "audio_cpp": "audio_cpp",
            "openai": "openai",
            "elevenlabs": "elevenlabs",
            "kokoro": "kokoro",
            "chatterbox": "chatterbox",
            "higgs": "higgs",
            "alltalk": "alltalk",
        }
        for alias, provider_id in aliases.items():
            if alias in query:
                return provider_id
        return None

    def _submit_category_search(self, query_text: str) -> None:
        query_text = self._sanitize_category_search_query(query_text)
        self.category_search_query = query_text
        self._apply_category_search_filter()
        category_values = self._filtered_category_values(query_text)
        if category_values:
            speech_target: SpeechTTSNavigationTarget | None = None
            if category_values[0] == SettingsCategoryId.SPEECH_TTS.value:
                provider_id = self._speech_tts_provider_from_search(query_text)
                if provider_id in BUILT_IN_TTS_PROVIDER_ORDER:
                    speech_target = SpeechTTSNavigationTarget(provider_id)
                    self._stage_speech_tts_navigation_target(speech_target)
            self._select_category(category_values[0], restore_focus=True)
            if speech_target is not None:
                self._after_category_panes(self._apply_speech_tts_navigation_context)
            # task-1715: if the query named a field, land ON the field --
            # focusing it also fires its inspector guidance. TASK-23109:
            # only when the match CAME from the field tier -- typing a
            # category's own title opens the category plainly instead of
            # stealing focus into its first coincidentally-matching field.
            opened = SettingsCategoryId(category_values[0])
            opened_summary = self._category_summary_by_id(opened)
            field = (
                self._top_field_match(query_text, opened)
                if self._search_match_is_field_landing(query_text, opened_summary)
                else None
            )
            if field is not None:
                field_id, field_label = field

                def _focus_matched_field() -> None:
                    self._land_search_focus_on_field(field_id, field_label)

                self._after_category_panes(_focus_matched_field)
            # task-1712: the filter has done its job -- clear it so the
            # rail returns to the full category map. Residue used to prune
            # the rail to the last search's matches for the rest of the
            # session, with no clear-filter affordance advertised.
            self.category_search_query = ""
            try:
                self.query_one("#settings-category-search", Input).value = ""
            except QueryError:
                pass
            self._apply_category_search_filter()

    def _land_search_focus_on_field(self, field_id: str, field_label: str) -> None:
        """Land Enter's field promise on a real, usable control.

        Review finding 3 (TASK-23109): a blind ``.focus()`` put focus on
        zero-region widgets inside collapsed ``Collapsible``s (keystrokes
        went into an off-screen Input) and silently no-opped on disabled
        widgets. Expand the enclosing Collapsibles and scroll the target
        into view first; if the target is disabled, keep the category open
        and say why in the search status line instead of doing nothing.

        Args:
            field_id: The matched control's widget id.
            field_label: Its indexed label, for the disabled explanation.
        """
        try:
            widget = self.query_one(f"#{field_id}")
        except QueryError:
            return
        if widget.disabled or any(
            getattr(node, "disabled", False) for node in widget.ancestors
        ):
            fallback_id = FIELD_SEARCH_DISABLED_FOCUS_FALLBACKS.get(field_id)
            if fallback_id is not None:
                try:
                    fallback = self.query_one(f"#{fallback_id}")
                except QueryError:
                    fallback = None
                if fallback is not None and not fallback.disabled:
                    widget = fallback
            if widget.disabled or any(
                getattr(node, "disabled", False) for node in widget.ancestors
            ):
                self._set_static_text(
                    "#settings-category-search-status",
                    f"'{field_label}' is disabled right now — its category is "
                    "open; enable the option that controls it first.",
                )
                return
        expanded = False
        for node in widget.ancestors:
            if isinstance(node, Collapsible) and node.collapsed:
                node.collapsed = False
                expanded = True

        def _focus_now() -> None:
            try:
                widget.scroll_visible(animate=False)
            except Exception:
                logger.debug("Search landing could not scroll to the field.")
            widget.focus()

        if expanded:
            # Let the expansion lay out before focusing, or the target still
            # has a zero region when focus arrives.
            self.call_after_refresh(_focus_now)
        else:
            _focus_now()

    def _category_state_banner_text(self, category: SettingsCategoryId) -> str:
        if (
            category is SettingsCategoryId.APPEARANCE
            and self._category_has_unsaved_changes(category)
        ):
            validation = self._appearance_validation_result()
            if not validation.valid:
                return f"State: Needs correction | {validation.message}"
        if (
            category is SettingsCategoryId.LIBRARY_RAG
            and self._category_has_unsaved_changes(category)
        ):
            validation = self._library_rag_validation_result()
            if not validation.valid:
                return f"State: Needs correction | {validation.message}"
        if (
            category is SettingsCategoryId.STORAGE
            and self._category_has_unsaved_changes(category)
        ):
            validation = self._storage_validation_result()
            if not validation.valid:
                return f"State: Needs correction | {validation.message}"
        if self._category_has_unsaved_changes(category):
            return "State: Unsaved changes | Save (s) or Revert (r) — switching categories keeps this draft."
        # task-1717: lead with the persistence badge -- the footer hints
        # already honestly come and go with each category's save model,
        # but nothing NAMED the model, so users trained on Save/Revert got
        # silent contract changes (five models coexist on this screen).
        badge = self._persistence_badge(category)
        return f"State: {badge} | {self._category_state_scope_text(category)}"

    def _persistence_badge(self, category: SettingsCategoryId) -> str:
        """Name the save model the active category uses (task-1717).

        Args:
            category: The active Settings category.

        Returns:
            A short badge such as "Draft — save with s" that leads the
            State banner in the same position on every category.
        """
        if category in GUIDED_SETTINGS_MUTATION_CATEGORIES:
            return "Draft — save with s"
        if category is SettingsCategoryId.PERSONAL_CONTEXT:
            return "Applies immediately"
        if category is SettingsCategoryId.IMAGE_GENERATION:
            return "Draft — save/revert below"
        if category is SettingsCategoryId.VIDEO_GENERATION:
            return "Draft — save/revert below"
        if category is SettingsCategoryId.SPLASH_SCREEN:
            return "Auto-saved"
        if category is SettingsCategoryId.WORKSPACES:
            return "Applies immediately"
        if category is SettingsCategoryId.AGENTS:
            return "Applies immediately"
        if category is SettingsCategoryId.NETWORK:
            # No SettingsDraft: edits stage in `self._network_pending`
            # until the screen-wide `s` reaches the Network save branch.
            return "Pending — save with s"
        if category is SettingsCategoryId.THEME:
            return "Managed in editor"
        if category is SettingsCategoryId.INTERNAL_PROMPTS:
            return "Per-item Save/Reset"
        if category is SettingsCategoryId.SCHEDULES:
            return "Applies immediately"
        if category is SettingsCategoryId.ADVANCED_CONFIG:
            return "Validate, then Save"
        return "Read-only here"

    def _category_state_scope_text(self, category: SettingsCategoryId) -> str:
        """The category-scope half of the State banner (after the badge)."""
        if category is SettingsCategoryId.ADVANCED_CONFIG:
            return "Save blocked until the text validates; backup before overwrite."
        if category is SettingsCategoryId.PROVIDERS_MODELS:
            return "Shared with Console"
        if category is SettingsCategoryId.SPEECH_TTS:
            return "Application-wide defaults; Studio preferences remain separate."
        if category is SettingsCategoryId.CONSOLE_BEHAVIOR:
            return "Changes affect global Console fallbacks after save."
        if category is SettingsCategoryId.LIBRARY_RAG:
            return "Defaults affect future Library/RAG retrieval and display."
        if category is SettingsCategoryId.IMAGE_GENERATION:
            return "Defaults affect future Console image generations."
        if category is SettingsCategoryId.VIDEO_GENERATION:
            return "Defaults affect future Console video generations."
        if category is SettingsCategoryId.DIAGNOSTICS:
            return "Validation and reload expose status without writing raw TOML."
        if category is SettingsCategoryId.APPEARANCE:
            return "Settings owns launch and web display defaults."
        if category is SettingsCategoryId.STORAGE:
            return "Changes apply on next launch; active handles stay unchanged."
        if category is SettingsCategoryId.PRIVACY_SECURITY:
            return (
                "Only the raw CLI unlock is editable; privacy posture and secrets "
                "remain read-only and redacted."
            )
        if category is SettingsCategoryId.PERSONAL_CONTEXT:
            return "Encrypted local profile; record and authority actions apply immediately."
        if category is SettingsCategoryId.SPLASH_SCREEN:
            return "Splash changes take effect as you make them."
        if category is SettingsCategoryId.WORKSPACES:
            return "Each action reversible: unarchive, rename again, or set active."
        if category is SettingsCategoryId.AGENTS:
            return "agent_runs.db (SQLite) — immediate CRUD, no draft"
        if category is SettingsCategoryId.THEME:
            return "Use the editor's Apply/Save/Reset buttons below."
        if category is SettingsCategoryId.INTERNAL_PROMPTS:
            return "Each prompt saves and resets on its own."
        if category is SettingsCategoryId.SCHEDULES:
            return (
                "Settings owns the global Watchlists briefing gate; Artifacts owns "
                "each collection cadence; schedules run while Chatbook is open."
            )
        # TASK-23104: the badge already leads the banner with "State: ..." --
        # scope text must never embed a second "State:" segment of its own
        # (domain categories used to render "State: Read-only here | State:
        # Read-only | ...").
        if category in DOMAIN_SETTINGS_CATEGORY_IDS:
            contract = self._domain_category_contract(category)
            return f"{contract.owner_destination} owns workflow actions and setup."
        return "Review readiness across Settings categories."

    def _render_category_state_banner(self, category: SettingsCategoryId) -> Static:
        banner = Static(
            self._category_state_banner_text(category),
            id="settings-category-state-banner",
            classes="settings-state-banner",
        )
        if self._category_has_unsaved_changes(category):
            banner.add_class("settings-dirty-category")
        return banner

    def _update_category_state_banner(self, category: SettingsCategoryId) -> None:
        try:
            banner = self.query_one("#settings-category-state-banner", Static)
        except QueryError:
            return
        banner.update(self._category_state_banner_text(category))
        if self._category_has_unsaved_changes(category):
            banner.add_class("settings-dirty-category")
        else:
            banner.remove_class("settings-dirty-category")

    @staticmethod
    def _normalise_appearance_int(value: object) -> int | str:
        text_value = str(value).strip()
        return int(text_value) if text_value.isdigit() else text_value

    def _stage_appearance_value(self, key: str, value: object) -> None:
        category = SettingsCategoryId.APPEARANCE
        draft = self._settings_drafts.setdefault(
            category, SettingsDraft(category=category)
        )
        draft.set_value(
            key,
            self._appearance_loaded_values().get(key),
            value,
        )
        if not draft.is_dirty:
            self._settings_drafts.pop(category, None)

    def _appearance_invalid_field_key(self) -> str | None:
        validation = self._appearance_validation_result()
        if validation.valid:
            return None
        message = validation.message
        if message.startswith("Theme"):
            return "default_theme"
        if message.startswith("Palette theme limit"):
            return "palette_theme_limit"
        if message.startswith("Font size"):
            return "font_size"
        if message.startswith("Density"):
            return "density"
        if message.startswith("Transcript style"):
            return "console_transcript_style"
        if message.startswith("Animations"):
            return "animations_enabled"
        if message.startswith("Reduce motion"):
            return "reduce_motion"
        if message.startswith("ASCII glyphs"):
            return "ascii_glyphs"
        if message.startswith("Smooth scrolling"):
            return "smooth_scrolling"
        if message.startswith("Library pane"):
            return "library_reader_library_open"
        if message.startswith("Items pane"):
            return "library_media_items_open"
        if message.startswith("Custom widths"):
            return "library_reader_custom_widths_enabled"
        if message.startswith("Library width"):
            return "library_reader_library_width"
        if message.startswith("Items width"):
            return "library_media_items_width"
        if message.startswith("Folder Files tree pane"):
            return "library_notes_files_tree_open"
        if message.startswith("Folder Files tree width"):
            return "library_notes_files_tree_width"
        for destination, label in LIBRARY_READER_DESTINATIONS[1:]:
            if message.startswith(f"{label} Items pane"):
                return f"library_{destination}_items_open"
            if message.startswith(f"{label} Items width"):
                return f"library_{destination}_items_width"
        return None

    def _appearance_field_selector(self, key: str) -> str | None:
        selectors = {
            "default_theme": "#settings-appearance-theme",
            "palette_theme_limit": "#settings-appearance-palette-theme-limit",
            "font_size": "#settings-appearance-font-size",
            "density": "#settings-appearance-density",
            "console_transcript_style": "#settings-appearance-transcript-style",
            "animations_enabled": "#settings-appearance-animations-enabled",
            "smooth_scrolling": "#settings-appearance-smooth-scrolling",
            "reduce_motion": "#settings-appearance-reduce-motion",
            "ascii_glyphs": "#settings-appearance-ascii-glyphs",
            "library_reader_library_open": "#settings-appearance-library-media-library-open",
            "library_media_items_open": "#settings-appearance-library-media-items-open",
            "library_reader_custom_widths_enabled": "#settings-appearance-library-media-custom-widths",
            "library_reader_library_width": "#settings-appearance-library-media-library-width",
            "library_media_items_width": "#settings-appearance-library-media-items-width",
            "library_notes_files_tree_open": "#settings-appearance-library-notes-files-tree-open",
            "library_notes_files_tree_width": "#settings-appearance-library-notes-files-tree-width",
        }
        for destination, _label in LIBRARY_READER_DESTINATIONS[1:]:
            selectors[f"library_{destination}_items_open"] = (
                f"#settings-appearance-library-{destination}-items-open"
            )
            selectors[f"library_{destination}_items_width"] = (
                f"#settings-appearance-library-{destination}-items-width"
            )
        return selectors.get(key)

    def _update_appearance_validation_classes(self) -> None:
        invalid_key = self._appearance_invalid_field_key()
        for key in (
            "default_theme",
            "palette_theme_limit",
            "font_size",
            "density",
            "console_transcript_style",
            "animations_enabled",
            "smooth_scrolling",
            "reduce_motion",
            "ascii_glyphs",
            "library_reader_library_open",
            "library_media_items_open",
            "library_reader_custom_widths_enabled",
            "library_reader_library_width",
            "library_media_items_width",
            "library_collections_items_open",
            "library_collections_items_width",
            "library_conversations_items_open",
            "library_conversations_items_width",
            "library_notes_items_open",
            "library_notes_items_width",
            "library_notes_files_tree_open",
            "library_notes_files_tree_width",
            "library_prompts_items_open",
            "library_prompts_items_width",
            "library_skills_items_open",
            "library_skills_items_width",
        ):
            selector = self._appearance_field_selector(key)
            if selector is None:
                continue
            try:
                widget = self.query_one(selector)
            except QueryError:
                continue
            widget.set_class(key == invalid_key, "settings-invalid-input")

    def _mark_appearance_settings_staged(self) -> None:
        category = SettingsCategoryId.APPEARANCE
        if self._category_has_unsaved_changes(category):
            validation = self._appearance_validation_result()
            self._appearance_result = (
                "Appearance defaults staged."
                if validation.valid
                else validation.message
            )
        else:
            self._appearance_result = "Appearance defaults match loaded values."
        self._set_static_text(
            "#settings-appearance-save-result", self._appearance_result
        )
        self._update_appearance_validation_classes()
        self._update_draft_status_widgets(category)

    def _appearance_theme_options(self) -> list[tuple[str, str]]:
        options: list[tuple[str, str]] = [
            ("Textual Dark", "textual-dark"),
            ("Textual Light", "textual-light"),
        ]
        seen = {value for _label, value in options}
        try:
            from tldw_chatbook.css.Themes.themes import ALL_THEMES
        except (ImportError, ModuleNotFoundError):
            ALL_THEMES = ()
        for theme in ALL_THEMES:
            theme_name = str(getattr(theme, "name", "") or "").strip()
            if not theme_name or theme_name in seen:
                continue
            seen.add(theme_name)
            options.append(
                (theme_name.replace("_", " ").replace("-", " ").title(), theme_name)
            )
        current_theme = str(self._appearance_setting_values()["default_theme"])
        if current_theme and current_theme not in seen:
            options.append((f"Current: {current_theme}", current_theme))
        return options

    def _appearance_bool_label(self, key: str) -> str:
        """Label for a boolean Appearance toggle button, from staged state.

        Args:
            key: An appearance-defaults key (``reduce_motion``,
                ``ascii_glyphs``, or ``smooth_scrolling``).

        Returns:
            ``"Enabled"`` or ``"Disabled"``, reflecting the draft value when
            one is staged, else the loaded value (the same draft-over-loaded
            precedence every other Appearance control renders from).
        """
        return "Enabled" if bool(self._appearance_setting_values()[key]) else "Disabled"

    def _appearance_media_layout_label(self, key: str) -> str:
        """Return state-in-text labels for Library layout preference buttons."""
        enabled = bool(self._appearance_setting_values()[key])
        if key == "library_reader_custom_widths_enabled":
            return "Custom widths" if enabled else "Automatic widths"
        return "Open" if enabled else "Collapsed"

    def _appearance_summary_text(self) -> str:
        values = self._appearance_setting_values()
        return (
            f"Theme {values['default_theme']} | Density {values['density']} | "
            f"Transcript {str(values['console_transcript_style']).replace('_', ' ')} | "
            f"Font {values['font_size']} | Palette limit {values['palette_theme_limit']}"
        )

