    @on(Button.Pressed, "#settings-switch-runtime-source")
    def handle_switch_runtime_source(self, event: Button.Pressed) -> None:
        """Open the runtime-source switch modal (callback-based, never wait)."""
        event.stop()
        from tldw_chatbook.Widgets.Settings_Widgets.server_switch_modal import (
            ServerSwitchModal,
        )

        state = self._runtime_source_state()
        raw_config = (getattr(self.app_instance, "app_config", {}) or {}).get(
            "COMPREHENSIVE_CONFIG_RAW", {}
        )
        api_config = (
            raw_config.get("tldw_api", {}) if isinstance(raw_config, dict) else {}
        )
        modal = ServerSwitchModal(
            current_source=str(getattr(state, "active_source", "local") or "local"),
            current_server_label=str(
                getattr(state, "last_known_server_label", "")
                or getattr(state, "active_server_id", "")
                or ""
            ),
            current_base_url=str(api_config.get("base_url") or ""),
            current_auth_token=str(api_config.get("auth_token") or ""),
        )
        self.app.push_screen(modal, self._handle_runtime_source_switch_result)

    def _handle_runtime_source_switch_result(self, result: dict | None) -> None:
        if not result:
            return
        self.run_worker(
            self._perform_runtime_source_switch(result),
            exclusive=True,
            group="settings-runtime-source-switch",
        )

    async def _perform_runtime_source_switch(self, result: dict) -> None:
        """Apply the modal decision: persist, rebind, switch, enroll Sync v2."""
        app = self.app_instance
        if result.get("action") == "local":
            switched = await app.handle_runtime_backend_changed("local")
            if not switched:
                return
            self.app.notify("Runtime source set to local.", severity="information")
            self._refresh_manual_sync_rows()
            return

        base_url = str(result.get("base_url") or "").strip()
        if not base_url:
            return

        from tldw_chatbook.Utils.input_validation import validate_url

        if not validate_url(base_url):
            self.app.notify(
                "Rejected server URL; nothing was changed.", severity="error"
            )
            return
        auth_token = str(result.get("auth_token") or "").strip()
        saved = save_settings_to_cli_config(
            {
                "tldw_api": {
                    "base_url": base_url,
                    "auth_token": auth_token,
                }
            }
        )
        if not saved:
            self.app.notify(
                "Server settings could not be saved; "
                "the previous source remains active.",
                severity="error",
            )
            return

        try:
            refreshed_config = load_settings(force_reload=True)
        except Exception as exc:
            logger.warning(
                "Saved server settings could not be loaded (exception_category=%s).",
                type(exc).__name__,
            )
            self.app.notify(
                "Server settings were saved but could not be activated; "
                "the previous source remains active.",
                severity="error",
            )
            return

        switched = await app.handle_runtime_backend_changed(
            "server",
            app_config_override=refreshed_config,
        )
        if not switched:
            return

        state = self._runtime_source_state()
        server_id = str(getattr(state, "active_server_id", "") or "").strip()
        if not server_id:
            self.app.notify(
                "Server could not be bound from the entered URL.", severity="error"
            )
            return

        if auth_token:
            provider = getattr(app, "server_context_provider", None)
            if provider is not None:
                try:
                    provider.store_static_server_credential(server_id, auth_token)
                except Exception as exc:
                    logger.warning(
                        "Server token could not be stored in the OS credential "
                        "store (exception_category=%s).",
                        type(exc).__name__,
                    )
                    self.app.notify(
                        "Server activated, but the token could not be saved to "
                        "the OS keyring; it remains saved in config.toml only.",
                        severity="warning",
                    )

        sync_scope_service = getattr(app, "sync_scope_service", None)
        prepare = getattr(sync_scope_service, "prepare_sync_v2_profile_mode", None)
        if callable(prepare):
            import platform

            try:
                summary = await prepare(
                    profile_mode="local_first_sync",
                    server_profile_id=server_id,
                    display_name=platform.node() or "tldw_chatbook",
                )
            except Exception as exc:
                logger.warning(
                    "Sync v2 profile preparation failed "
                    "(mode=local_first_sync, exception_category=%s).",
                    type(exc).__name__,
                )
                self.app.notify(
                    "Server activated, but Sync v2 setup could not be completed.",
                    severity="warning",
                )
            else:
                dataset = str(summary.get("dataset_id") or "unknown")
                self.app.notify(
                    f"Server activated; Sync v2 prepared (dataset {dataset}).",
                    severity="information",
                )
        else:
            self.app.notify(
                "Server activated. Sync v2 service is unavailable in this runtime.",
                severity="warning",
            )
        self._refresh_manual_sync_rows()

    @on(Button.Pressed, "#settings-manual-sync-preview")
    def handle_manual_sync_preview(self, event: Button.Pressed) -> None:
        event.stop()
        self.manual_sync_rows = (
            ("Manual sync status", "loading"),
            ("Manual sync preview", "Refreshing manual Sync v2 preview."),
            ("Pending outgoing", "Loading"),
        )
        self._refresh_manual_sync_rows()

    @on(Button.Pressed, "#settings-manual-sync-run")
    def handle_manual_sync_run(self, event: Button.Pressed) -> None:
        event.stop()
        # task-1367: this pushes pending Notes/Chat changes to a server, so
        # confirm first -- seeded with the pending counts the preview rows
        # already loaded; only the confirm path runs the sync.
        pending_copy = next(
            (
                value
                for label, value in self.manual_sync_rows
                if label == "Pending outgoing"
            ),
            "unknown",
        )
        # task-1369: readable fallback when the preview counts have not
        # loaded yet -- never interpolate "Loading"/"unknown" into the copy.
        if pending_copy.strip().lower() in {"", "loading", "refreshing", "unknown"}:
            pending_line = "Sync will push all pending changes."
        else:
            pending_line = f"Pending outgoing: {pending_copy}"

        async def _confirmed_run() -> None:
            self._manual_sync_run_token += 1
            run_token = self._manual_sync_run_token
            self._manual_sync_run_in_flight = True
            self.manual_sync_rows = (
                ("Manual sync status", "running"),
                (
                    "Manual sync result",
                    "Manual Sync is running after explicit user request.",
                ),
                ("Pending outgoing", "Refreshing"),
            )
            try:
                self._manual_sync_run_worker(run_token)
            except Exception:
                # task-1369 (review): a synchronous raise at the call site
                # (before the worker exists) must not strand the flag.
                self._manual_sync_run_in_flight = False
                logger.warning(
                    "Failed to start Settings manual sync run worker.",
                    exc_info=True,
                )
                self._apply_manual_sync_rows(
                    (
                        ("Manual sync status", "failed"),
                        (
                            "Manual sync result",
                            "Manual Sync run could not be started.",
                        ),
                        ("Pending outgoing", "unknown"),
                    )
                )

        self.app.push_screen(
            ConfirmationDialog(
                title="Run manual sync",
                message=(
                    "Push pending Notes/Chat changes to the server now?\n\n"
                    f"{pending_line}"
                ),
                confirm_label="Push to server",
                cancel_label="Cancel",
                confirm_callback=_confirmed_run,
            )
        )

    @on(Button.Pressed, ".settings-notes-adoption-action")
    def handle_notes_adoption_action(self, event: Button.Pressed) -> None:
        """Resolve a content-free Notes adoption review and resume enrollment."""

        event.stop()
        actions = {
            "settings-notes-adoption-merge": "merge",
            "settings-notes-adoption-rename-local": "rename_local",
            "settings-notes-adoption-keep-local": "keep_local",
        }
        action = actions.get(event.button.id or "")
        review_id = self._manual_sync_adoption_review_id
        if action is None or review_id is None:
            return
        new_name: str | None = None
        if action == "rename_local":
            new_name = self.query_one(
                "#settings-notes-adoption-new-name", Input
            ).value.strip()
            if not new_name:
                self._apply_manual_sync_rows(
                    (
                        ("Manual sync status", "conflict"),
                        (
                            "Manual sync result",
                            "Enter a new local display name before renaming.",
                        ),
                        ("Pending outgoing", "blocked by adoption review"),
                    )
                )
                return
        control = getattr(self.app_instance, "manual_sync_control_service", None)
        sync_scope = self._active_sync_scope(self._active_workspace_record())
        server_profile_id = sync_scope["server_profile_id"]
        if control is None or not server_profile_id:
            self._apply_manual_sync_rows(
                (
                    ("Manual sync status", "blocked"),
                    (
                        "Manual sync result",
                        "Manual Sync requires an active server profile.",
                    ),
                    ("Pending outgoing", "none"),
                )
            )
            return
        try:
            resolved = control.resolve_notes_organization_adoption(
                server_profile_id=server_profile_id,
                authenticated_principal_id=sync_scope["authenticated_principal_id"],
                workspace_scope=sync_scope["workspace_scope"],
                review_id=review_id,
                action=action,
                new_name=new_name,
            )
        except Exception as exc:
            logger.warning("Failed to resolve Notes adoption review.", exc_info=True)
            self._apply_manual_sync_rows(
                (
                    ("Manual sync status", "failed"),
                    (
                        "Manual sync result",
                        f"Adoption review failed: {type(exc).__name__}",
                    ),
                    ("Pending outgoing", "blocked by adoption review"),
                )
            )
            return
        if not resolved:
            self._apply_manual_sync_rows(
                (
                    ("Manual sync status", "conflict"),
                    ("Manual sync result", "Adoption review remains unresolved."),
                    ("Pending outgoing", "blocked by adoption review"),
                )
            )
            return
        self._manual_sync_adoption_review_id = None
        self._manual_sync_run_token += 1
        run_token = self._manual_sync_run_token
        self._manual_sync_run_in_flight = True
        self.manual_sync_rows = (
            ("Manual sync status", "running"),
            ("Manual sync result", "Resuming Notes organization enrollment."),
            ("Pending outgoing", "Refreshing"),
        )
        try:
            self._manual_sync_run_worker(run_token)
        except Exception:
            self._manual_sync_run_in_flight = False
            logger.warning(
                "Failed to resume Notes organization enrollment.",
                exc_info=True,
            )
            self._apply_manual_sync_rows(
                (
                    ("Manual sync status", "failed"),
                    ("Manual sync result", "Enrollment could not be resumed."),
                    ("Pending outgoing", "unknown"),
                )
            )

